  help = document.createElement("div");
  help.className = "ln footer-help";
  help.textContent = "↑ ↓ move · enter select";
  out.appendChild(help);
  btns[0].focus({ preventScroll: true });
}

// Multi-select: space toggles, enter confirms. Mirrors the agent checklist.
function multi(title, options, selected, next) {
  line(title, "q");
  var box = document.createElement("div");
  box.className = "opts";
  box.setAttribute("role", "listbox");
  box.setAttribute("aria-multiselectable", "true");
  box.setAttribute("aria-label", title);
  var idx = 0, btns = [], help = null;

  options.forEach(function (o, i) {
    var b = document.createElement("button");
    b.className = "opt"; b.type = "button";
    b.setAttribute("role", "option");
    var mk = document.createElement("span"); mk.className = "mk"; mk.textContent = ">";
    var lb = document.createElement("span"); lb.className = "lb";
    var ht = document.createElement("span"); ht.className = "ht";
    ht.textContent = DETECTED.indexOf(o[0]) >= 0 ? "detected" : "";
    b.appendChild(mk); b.appendChild(lb); b.appendChild(ht);
    b.addEventListener("click", function () { toggle(i); });
    btns.push(b); box.appendChild(b);
  });

  function sync() {
    btns.forEach(function (b, i) {
      var on = selected.indexOf(options[i][0]) >= 0;
      b.setAttribute("aria-selected", i === idx ? "true" : "false");
      b.setAttribute("aria-checked", on ? "true" : "false");
      b.querySelector(".lb").textContent = (on ? "◼ " : "◻ ") + options[i][1];
    });
  }
  function toggle(i) {
    idx = i;
    var v = options[i][0], at = selected.indexOf(v);
    if (at >= 0) { selected.splice(at, 1); } else { selected.push(v); }
    sync(); btns[i].focus({ preventScroll: true });
  }
  function done() {
    btns.forEach(function (b) { b.disabled = true; b.style.cursor = "default"; });
    if (help && help.parentNode) { help.parentNode.removeChild(help); }
    if (doneBtn && doneBtn.parentNode) { doneBtn.parentNode.removeChild(doneBtn); }
    next();
  }
  keyNav(btns, function () { return idx; }, function (v) { idx = v; sync(); }, done,
    function (e, i) { if (e.key === " ") { e.preventDefault(); toggle(i); } });

  out.appendChild(box);
  var doneBtn = document.createElement("button");
  doneBtn.className = "opt"; doneBtn.type = "button";
  doneBtn.innerHTML = '<span class="mk">&gt;</span><span class="lb">✓ Continue</span><span class="ht"></span>';
  doneBtn.addEventListener("click", done);
  out.appendChild(doneBtn);
  help = document.createElement("div");
  help.className = "ln footer-help";
  help.textContent = "space toggle · enter continue";
  out.appendChild(help);
  sync();
  btns[0].focus({ preventScroll: true });
}

