function planRows() {
  var mirrorNote = S.mirror && S.mirror.indexOf("existing") >= 0 ? "existing mirror" : "new mirror";
  var rows = [["region", C.region + "  (" + (S.connect ? mirrorNote : regionLabel()) + ")"],
              ["agents", agentLabels()]];
  if (S.connect) {
    rows.push(["origin", C.repoint
      ? (S.origin === null || scenario !== "repo" ? "Entire (native)" : "Entire (mirrors GitHub)")
      : "unchanged — stays on GitHub"]);
  }
  rows.push(["telemetry", C.telemetry ? "on" : "off"]);
  return rows;
}

function printRows(rows, cls) {
  var w = 0;
  rows.forEach(function (r) { w = Math.max(w, r[0].length); });
  rows.forEach(function (r) {
