    origin: "entire enable", telemetry: "entire configure --telemetry=" + (C.telemetry ? "false" : "true") };
  var w1 = 0, w2 = 0;
  rows.forEach(function (r) { w1 = Math.max(w1, r[0].length); w2 = Math.max(w2, r[1].length); });
  rows.forEach(function (r) {
    var d = document.createElement("div"); d.className = "ln";
