      line("  ✗ Not on Entire yet — it will be created and hosted here", "bad");
      line("");
      S.mirror = "new";

        S.mirror = "new";
        wait("gate"); return;
      }
      line("  ⠋ Checking Entire's access to acme/widget…", "dim");
      if (known === "connected") {
        S.app = "installed"; paintState();
        line("  ✓ Entire already has access   (installed by someone on your team)", "ok");
        line("");
        wait("check_mirror"); return;
      }
      line("  ✗ Entire has no access to acme/widget", "bad");
      line("");
      wait("app");
    },

    check_mirror: function () {
