func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
	remotes, err := listGitRemotes(ctx, "")
	if err != nil {
		return "", "", "", err
	}
	if remotes[defaultMirrorRemote] {
		raw, readErr := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
		if readErr != nil {
			return "", "", "", fmt.Errorf("read origin remote: %w", readErr)
		}
		return configureRepoIdentityFromURL(raw, "origin")
	}

	// A GitHub clone normally has origin, but remote names are local and users
	// can rename it or clone with -o. When origin is absent, accept a uniquely
	// identifiable GitHub repository under any remote name.
	names := make([]string, 0, len(remotes))
	for name := range remotes {
		names = append(names, name)
	}
	sort.Strings(names)
	type candidate struct {
		owner string
		repo  string
		clean string
	}
	byRepository := make(map[string]candidate)
	for _, name := range names {
		raw, readErr := gitremote.GetRemoteURL(ctx, name)
		if readErr != nil {
			return "", "", "", fmt.Errorf("read remote %q: %w", name, readErr)
		}
		info, parseErr := gitremote.ParseURL(raw)
		if parseErr != nil || info.Forge != mirrorUseForge {
			continue
		}
		clean, cleanErr := cleanRemoteURLForReport(raw)
		if cleanErr != nil {
			return "", "", "", fmt.Errorf("clean remote %q: %w", name, cleanErr)
		}
		candidateOwner := strings.ToLower(info.Owner)
		candidateRepo := strings.ToLower(info.Repo)
		key := candidateOwner + "/" + candidateRepo
		if _, exists := byRepository[key]; !exists {
			byRepository[key] = candidate{owner: candidateOwner, repo: candidateRepo, clean: clean}
		}
	}
	if len(byRepository) == 0 {
		return "", "", "", errors.New("interactive configure currently requires a GitHub remote")
	}
	if len(byRepository) > 1 {
		repositories := make([]string, 0, len(byRepository))
		for repository := range byRepository {
			repositories = append(repositories, repository)
		}
		sort.Strings(repositories)
		return "", "", "", fmt.Errorf("multiple GitHub repositories found in remotes (%s); configure cannot choose", strings.Join(repositories, ", "))
	}
	for _, found := range byRepository {
		return found.owner, found.repo, found.clean, nil
	}
	return "", "", "", errors.New("GitHub remote resolution produced no repository")
}

func configureRepoIdentityFromURL(raw, remoteName string) (owner, repo, cleanRemote string, err error) {
	info, err := gitremote.ParseURL(raw)
	if err != nil {
		return "", "", "", fmt.Errorf("parse %s remote: %w", remoteName, err)
	}
	if info.Forge != mirrorUseForge {
		return "", "", "", fmt.Errorf("interactive configure currently requires a GitHub remote; %q is not GitHub", remoteName)
	}
	clean, err := cleanRemoteURLForReport(raw)
	if err != nil {
		return "", "", "", err
	}
	return strings.ToLower(info.Owner), strings.ToLower(info.Repo), clean, nil
}

func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
	target, err := deps.resolveAuth(ctx)
	if err != nil {
		return nil, err
	}
	if target.token != "" {
		if err := api.RequireSecureURL(target.coreURL); err != nil {
			return nil, fmt.Errorf("context login server URL check: %w", err)
		}
		if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
			return profile, nil
		} else if !isKeychainTokenRejected(profileErr) {
			return nil, fmt.Errorf("validate login: %w", profileErr)
		}
	}

	if err := deps.runLogin(ctx, outW, errW); err != nil {
		return nil, fmt.Errorf("login: %w", err)
	}
	target, err = deps.resolveAuth(ctx)
	if err != nil {
		return nil, err
	}
	if target.token == "" {
		return nil, errors.New("login completed without an active session")
	}
	if err := api.RequireSecureURL(target.coreURL); err != nil {
		return nil, fmt.Errorf("context login server URL check: %w", err)
	}
	profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
	if err != nil {
		return nil, fmt.Errorf("validate login: %w", err)
	}
	fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
	return profile, nil
}

func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, nonInteractive bool, deps configureFlowDeps) error {
	fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
	installURL := strings.TrimSpace(initial.InstallURL)
	if installURL == "" {
		fmt.Fprintln(errW, "  Entire did not provide a GitHub App installation URL.")
		fmt.Fprintln(errW, "  Please try again later or contact Entire support.")
		return NewSilentError(errors.New("GitHub App installation URL unavailable"))
	}

	admin, adminErr := deps.githubAdmin(ctx, owner, repo)
	if adminErr == nil && !admin {
		fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
		fmt.Fprintln(errW, "  Send them this link to continue:")
		fmt.Fprintf(errW, "\n  %s\n", installURL)
		return NewSilentError(errors.New("GitHub app installation required"))
	}
	if adminErr != nil {
		switch {
		case errors.Is(adminErr, errConfigureGHUnavailable):
			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not installed.")
			fmt.Fprintln(errW, "  Install it from https://cli.github.com/ and run `gh auth login` for future checks.")
		case errors.Is(adminErr, errConfigureGHUnauthenticated):
			fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not authenticated.")
			fmt.Fprintln(errW, "  Run `gh auth login` for future checks.")
		default:
			fmt.Fprintf(errW, "  Could not verify GitHub admin access: %v\n", adminErr)
		}
		fmt.Fprintln(errW, "  If you administer this repository, you can still continue with the installation link.")
		fmt.Fprintln(errW)
	}

	fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
	fmt.Fprintf(outW, "  %s\n\n", installURL)
	if nonInteractive {
		return NewSilentError(errors.New("GitHub app installation required; install it with the URL above, then rerun 'entire configure --yes'"))
	}
	if err := deps.openURL(ctx, installURL); err != nil {
		fmt.Fprintln(outW, "  Open the link above in your browser.")
	}
	stop := startSpinner(errW, "Waiting for installation")
	stopped := false
	defer func() {
		if !stopped {
			stop(false)
		}
	}()

	waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
	defer cancel()
	if err := waitForConfigureRepoAccess(waitCtx, reporter, cleanRemote, configureAccessPollInterval, configureAccessMaxErrors); err != nil {
		return err
	}
	stop(true)
	stopped = true
	fmt.Fprintln(outW, "✓ Access granted")
	return nil
}

func waitForConfigureRepoAccess(ctx context.Context, reporter configureAccessReporter, cleanRemote string, pollInterval time.Duration, maxErrors int) error {
	ticker := time.NewTicker(pollInterval)
	defer ticker.Stop()
	consecutiveErrors := 0
	for {
		select {
		case <-ctx.Done():
			return fmt.Errorf("waiting for GitHub app installation: %w", ctx.Err())
		case <-ticker.C:
			access, err := reporter.ReportEnable(ctx, cleanRemote)
			if err != nil {
				consecutiveErrors++
				if consecutiveErrors >= maxErrors {
					return fmt.Errorf("check repository access while waiting for installation: %w", err)
				}
				continue
			}
			consecutiveErrors = 0
			if access != nil && access.Connected {
