package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"charm.land/huh/v2"
	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// `entire enable-next` is the proposed onboarding flow, running beside
// `entire enable` rather than replacing it so both can be exercised on the
// same repository before either is retired.
//
// The shape it implements: everything with a sensible default is decided, and
// the one genuine fork — does this repository connect to Entire, or record
// sessions locally — is the only question asked. Region, agents, the origin
// rewrite and telemetry are chosen for us and printed back with the command
// that changes each one. Session capture works either way, so nothing on the
// connect path (no account, no GitHub App, no reachable control plane) is
// allowed to end the command: it degrades to the local answer and says so.
//
// Everything it applies goes through the same primitives `enable` uses
// (runEnableInteractive for hooks/settings, the mirror + remote helpers for
// the connect path). Only the flow — the question, the plan, the closing
// summary — is new, which is what makes the two commands comparable.

// The two answers to the one question. Values, not booleans, so the select's
// binding reads as itself in the code that renders the plan.
const (
	enableNextAnswerConnect = "connect"
	enableNextAnswerLocal   = "local"
)

// enableNextOptions are enable-next's flags. Deliberately a small set: the
// interactive flow asks one question and decides the rest, so these exist to
// (a) answer that question without a terminal, and (b) override a decision
// the flow would otherwise make for you. Anything that only edits settings
// after setup stays on `entire configure`.
type enableNextOptions struct {
	// connect / localOnly answer the one question non-interactively.
	connect   bool
	localOnly bool
	// region names the cluster a new mirror is created in (slug or host),
	// overriding the login's home jurisdiction default.
	region string
	// agents overrides the detected-agent default.
	agents []string
	// telemetry is the value written when the flow does not ask.
	telemetry bool
	// noConfirm applies the plan without the confirmation step — the second
	// of the two endings this command exists to compare.
	noConfirm bool
	// yes implies connect + noConfirm and accepts every default, so a
	// non-interactive caller gets the whole flow in one invocation.
	yes bool
	// initRepo / noInitRepo answer the "initialize a git repository?" prompt
	// non-interactively.
	initRepo   bool
	noInitRepo bool

	forceHooks   bool
	useLocal     bool
	useProject   bool
	insecureHTTP bool
}

// enableNextIdentity is what enable-next knows about the repository before it
// asks anything: where it is, what to call it in prose, and the GitHub
// coordinates the connect path needs. An already-mirrored origin
// (entire://…/gh/owner/repo) still yields owner/repo — gitremote maps the
// forge prefix back — so re-running on a connected repo is not a special case.
type enableNextIdentity struct {
	root  string
	label string
	owner string
	repo  string
	// cleanRemote is the credential-free https URL the enable report is keyed
	// on. Empty when the repo has no GitHub origin.
	cleanRemote string
	originURL   string
	hasOrigin   bool
	// originIsEntire is true when origin already points through Entire, which
	// makes the repoint step a no-op rather than a rewrite.
	originIsEntire bool
}

func (i enableNextIdentity) isGitHub() bool { return i.owner != "" && i.repo != "" }

func (i enableNextIdentity) fullName() string { return i.owner + "/" + i.repo }

func newEnableNextCmd() *cobra.Command {
	var o enableNextOptions

	cmd := &cobra.Command{
		Use:   "enable-next",
		Short: "Enable Entire in the current repository (proposed onboarding flow)",
		Long: `Enable Entire using the proposed onboarding flow.

Runs beside 'entire enable' so both flows can be tried on the same repository.
It asks one question — connect this repository to Entire, or record sessions
only in it — and decides everything else: the region (your login's home
jurisdiction), which agents to capture (the ones detected here), whether origin
is repointed at Entire, and telemetry. Every decision is printed back with the
command that changes it.

Session capture works with or without an account, so nothing on the connect
path ends the command: a missing login, a GitHub App nobody has installed yet,
or an unreachable control plane leaves you with a working local setup and a
message saying what to run next.

Examples:
  entire enable-next                     # ask the one question, confirm the plan
  entire enable-next --no-confirm        # ask the one question, then apply
  entire enable-next --local-only        # record sessions in this repo only
  entire enable-next --connect --yes     # non-interactive, accept every default`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runEnableNext(cmd, o, newEnableNextDeps(o.insecureHTTP))
		},
	}

	cmd.Flags().BoolVar(&o.connect, "connect", false, "Answer the setup question with \"connect to Entire\" instead of asking")
	cmd.Flags().BoolVar(&o.localOnly, "local-only", false, "Answer the setup question with \"just my repo\" instead of asking")
	cmd.Flags().StringVar(&o.region, "region", "", "Cluster slug or host for a new mirror (default: your login's home jurisdiction)")
	cmd.Flags().StringSliceVar(&o.agents, agentFlagName, nil, "Agents to capture (repeatable; default: the agents detected in this repository)")
	cmd.Flags().BoolVar(&o.telemetry, flagTelemetry, true, "Enable anonymous usage analytics")
	cmd.Flags().BoolVar(&o.noConfirm, "no-confirm", false, "Apply the plan without the confirmation step")
	cmd.Flags().BoolVarP(&o.yes, "yes", "y", false, "Accept every default without prompting (implies --connect and --no-confirm)")
	cmd.Flags().BoolVar(&o.initRepo, "init-repo", false, "If this is not a git repository, initialize one without asking")
	cmd.Flags().BoolVar(&o.noInitRepo, "no-init-repo", false, "If this is not a git repository, exit instead of asking")
	cmd.Flags().BoolVarP(&o.forceHooks, flagForce, "f", false, "Force reinstall hooks (removes existing Entire hooks first)")
	cmd.Flags().BoolVar(&o.useLocal, "local", false, "Write settings to .entire/settings.local.json instead of .entire/settings.json")
	cmd.Flags().BoolVar(&o.useProject, "project", false, "Write settings to .entire/settings.json even if it already exists")
	addInsecureHTTPAuthFlag(cmd, &o.insecureHTTP)

	cmd.MarkFlagsMutuallyExclusive("connect", "local-only")
	cmd.MarkFlagsMutuallyExclusive("local-only", "yes")
	cmd.MarkFlagsMutuallyExclusive("init-repo", "no-init-repo")

	return cmd
}

func runEnableNext(cmd *cobra.Command, o enableNextOptions, deps enableNextDeps) error {
	cmd.SilenceUsage = true
	ctx := cmd.Context()
	outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()

	if o.yes {
		o.connect = true
		o.noConfirm = true
	}
	if err := validateSetupFlags(o.useLocal, o.useProject); err != nil {
		return err
	}

	// Discover external agent plugins before any agent lookup, so --agent and
	// the picker see them on a repo whose external_agents setting does not
	// exist yet (the same reason the setup flow does this first).
	external.DiscoverAndRegisterAlways(ctx)

	if _, err := paths.WorktreeRoot(ctx); err != nil {
		if err := enableNextInitRepo(ctx, outW, errW, o, deps); err != nil {
			return err
		}
	}

	// Building the logger writes under .entire, so it happens only after every
	// check that can still reject this invocation — a rejected enable must
	// leave an untouched repository untouched (see newLogger).
	ensureLogger(cmd)
	ctx = cmd.Context()

	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("resolve repository root: %w", err)
	}
	ident := resolveEnableNextIdentity(ctx, root)

	plan := enableNextPlan{
		agents:       enableNextDefaultAgents(ctx, o),
		telemetry:    o.telemetry,
		githubOrigin: ident.isGitHub(),
	}
	if len(o.agents) > 0 {
		selected, agentErr := enableNextAgentNames(o.agents)
		if agentErr != nil {
			return agentErr
		}
		plan.agents = selected
	}
	if len(plan.agents) == 0 {
		printMissingAgentError(errW)
		return NewSilentError(errors.New("no agents available"))
	}

	printEnableNextDetected(outW, plan.agents)

	answer, err := askEnableNextQuestion(ctx, outW, ident, o)
	if err != nil {
		return err
	}
	if answer == "" {
		// Cancelled at the one question: nothing has been written yet, so
		// there is nothing to unwind or report beyond the cancellation.
		return nil
	}
	plan.connect = answer == enableNextAnswerConnect

	var conn *enableNextConnection
	if plan.connect {
		conn, err = resolveEnableNextConnection(ctx, outW, errW, ident, o, deps)
		if err != nil {
			return err
		}
		if conn == nil {
			// The connect path could not complete and said why. Capture still
			// works, which is the whole reason it degrades instead of exiting.
			plan.connect = false
		} else {
			plan.region = conn.region
			plan.existingMirror = conn.existing
			plan.repointOrigin = ident.isGitHub()
		}
	}

	confirmed, err := confirmEnableNextPlan(ctx, outW, errW, &plan, conn, o)
	if err != nil {
		return err
	}
	if !confirmed {
		fmt.Fprintln(outW, "Setup cancelled. Nothing was written.")
		return nil
	}

	fmt.Fprintln(outW)
	if plan.connect && conn != nil {
		if err := applyEnableNextConnection(ctx, outW, errW, ident, plan, conn, deps); err != nil {
			return err
		}
	}
	if err := applyEnableNextLocal(ctx, outW, plan, o); err != nil {
		return err
	}

	printEnableNextEpilogue(outW, plan, ident)
	return nil
}

// enableNextInitRepo handles being run outside a git repository: confirm, then
// `git init` plus a git identity. It deliberately stops there — no GitHub repo
// is created and no commit is made, because the closing summary already tells
// you to commit the configuration and names the tool that publishes a
// repository. Reaching for enable before `git init` is the narrow case; the
// flow it gets is the short one.
func enableNextInitRepo(ctx context.Context, outW, errW io.Writer, o enableNextOptions, deps enableNextDeps) error {
	dir, err := os.Getwd() //nolint:forbidigo // no repository yet; git init runs in the process's directory
	if err != nil {
		return fmt.Errorf("get working directory: %w", err)
	}

	proceed := o.initRepo || o.yes
	switch {
	case o.noInitRepo:
		proceed = false
	case proceed:
	case !interactive.CanPromptInteractively():
		proceed = false
	default:
		answer, promptErr := deps.confirmInit(ctx, dir)
		if promptErr != nil {
			return promptErr
		}
		proceed = answer
	}
	if !proceed {
		fmt.Fprintln(errW, "Not a git repository. Please run 'entire enable-next' from within a git")
		fmt.Fprintln(errW, "repository, or pass --init-repo to initialize one here.")
		return NewSilentError(errors.New("not a git repository"))
	}

	printBootstrapSection(outW, "Setting up git repository")
	if err := gitInit(ctx, deps.runner, dir); err != nil {
		return fmt.Errorf("git init: %w", err)
	}
	// Drop the cached worktree root so the paths lookups below see the repo
	// that was just created.
	paths.ClearWorktreeRootCache()
	fmt.Fprintln(outW, "  ✓ Initialized empty git repository")
	if err := ensureGitIdentity(ctx, outW, errW, deps.runner, dir); err != nil {
		return err
	}
	fmt.Fprintln(outW)
	return nil
}

// resolveEnableNextIdentity reads what the repository says about itself. Every
// lookup is best-effort: a repo with no origin, an unparseable remote or a
// non-GitHub forge is not an error here, it just means the connect path has no
// GitHub coordinates to work with and says so when it gets there.
func resolveEnableNextIdentity(ctx context.Context, root string) enableNextIdentity {
	ident := enableNextIdentity{root: root, label: filepath.Base(root)}

	raw, err := gitremote.GetRemoteURLInDir(ctx, root, defaultMirrorRemote)
	if err != nil || strings.TrimSpace(raw) == "" {
		return ident
	}
	ident.hasOrigin = true
	ident.originURL = strings.TrimSpace(raw)

	info, err := gitremote.ParseURL(ident.originURL)
	if err != nil {
		return ident
	}
	ident.originIsEntire = info.Protocol == gitremote.ProtocolEntire
	if info.Forge != mirrorUseForge || info.Owner == "" || info.Repo == "" {
		return ident
	}
	ident.owner = strings.ToLower(info.Owner)
	ident.repo = strings.ToLower(info.Repo)
	ident.label = ident.fullName()
	ident.cleanRemote = cleanRemoteURLForReport(info)
	return ident
}

// enableNextDefaultAgents is the agent decision, made rather than asked: the
// agents whose hooks are already installed on a re-run, else the built-in
// agents detected in this repository, else the default agent so a repo with no
// detectable agent still gets a working setup. The edit path behind the
// confirmation is where this becomes a question.
func enableNextDefaultAgents(ctx context.Context, o enableNextOptions) []types.AgentName {
	if installed := GetAgentsWithHooksInstalled(ctx); len(installed) > 0 {
		return installed
	}
	var detected []types.AgentName
	for _, ag := range agent.DetectAll(ctx) {
		if isBuiltInAgent(ag) {
			detected = append(detected, ag.Name())
		}
	}
	if len(detected) > 0 {
		return detected
	}
	if def := agent.Default(); def != nil {
		return []types.AgentName{def.Name()}
	}
	_ = o
	return nil
}

// enableNextAgentNames resolves --agent values, rejecting an unknown name
// rather than silently enabling fewer agents than asked for.
func enableNextAgentNames(names []string) ([]types.AgentName, error) {
	resolved := make([]types.AgentName, 0, len(names))
	for _, raw := range names {
		name := strings.TrimSpace(raw)
		if name == "" {
			continue
		}
		if _, err := agent.Get(types.AgentName(name)); err != nil {
			return nil, fmt.Errorf("unknown agent %q (available: %s)", name, strings.Join(agent.StringList(), ", "))
		}
		resolved = append(resolved, types.AgentName(name))
	}
	if len(resolved) == 0 {
		return nil, errors.New("--agent was given no usable value")
	}
	return resolved, nil
}

func printEnableNextDetected(w io.Writer, agents []types.AgentName) {
	if len(agents) == 0 {
		return
	}
	fmt.Fprintf(w, "  %s detected\n\n", strings.Join(agentDisplayNames(agents), " and "))
}

// askEnableNextQuestion asks the one question. The disclosure above it is not
// a choice: session history lives in this repository and commits carry a
// checkpoint trailer whichever answer is given, so it is stated rather than
// offered. Returns "" when the user cancelled.
func askEnableNextQuestion(ctx context.Context, w io.Writer, ident enableNextIdentity, o enableNextOptions) (string, error) {
	switch {
	case o.localOnly:
		return enableNextAnswerLocal, nil
	case o.connect:
		return enableNextAnswerConnect, nil
	case !interactive.CanPromptInteractively():
		// Connecting signs in, talks to the control plane and rewrites origin.
		// None of that may happen because a script did not say so.
		fmt.Fprintln(w, "No interactive terminal, and the setup question is unanswered.")
		fmt.Fprintln(w, "Pass --connect (connect this repository to Entire) or --local-only")
		fmt.Fprintln(w, "(record sessions in this repository only).")
		return "", NewSilentError(errors.New("setup question unanswered"))
	}

	connectHint := "session history synced to your account"
	if ident.isGitHub() {
		connectHint = "origin → Entire · pushes forwarded to GitHub"
	}
	answer := enableNextAnswerConnect
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title(fmt.Sprintf("Set up Entire in %s", ident.label)).
				Description("Session history is stored in this repo, and commits get a\ncheckpoint trailer. That happens either way.").
				Options(
					huh.NewOption("Connect to Entire  —  "+connectHint, enableNextAnswerConnect),
					huh.NewOption("Just my repo       —  origin untouched · no account", enableNextAnswerLocal),
				).
				Value(&answer),
		),
	)
	if err := form.RunWithContext(ctx); err != nil {
		if cancelErr := handleFormCancellation(w, "Setup", err); cancelErr != nil {
			return "", cancelErr
		}
		return "", nil
	}
	return answer, nil
}

// applyEnableNextLocal writes everything that is local to the repository:
// agent hooks, the .entire directory, settings, and the git hook. It routes
// through runEnableInteractive so enable-next and enable apply identical
// state — only the presentation around it differs.
func applyEnableNextLocal(ctx context.Context, w io.Writer, plan enableNextPlan, o enableNextOptions) error {
	agents := make([]agent.Agent, 0, len(plan.agents))
	for _, name := range plan.agents {
		ag, err := agent.Get(name)
		if err != nil {
			return fmt.Errorf("failed to get agent %s: %w", name, err)
		}
		agents = append(agents, ag)
	}

	opts := EnableOptions{
		UseLocalSettings:   o.useLocal,
		UseProjectSettings: o.useProject,
		ForceHooks:         o.forceHooks,
		Telemetry:          plan.telemetry,
		// The plan was presented and accepted, so the questions behind these
		// flags have already been answered: Yes applies the decided telemetry
		// value instead of prompting for it, and SuppressAdditionalSetup keeps
		// the history-import offer out of a flow that has just printed what it
		// is going to do.
		Yes:                     true,
		SuppressAdditionalSetup: true,
		SuppressDoneMessage:     true,
	}
	return runEnableInteractive(ctx, w, agents, opts)
}

// printEnableNextEpilogue closes the flow: what was decided and how to change
// it, then the commit the user still owns. Nothing is committed for them —
// which is why the commit line is the last thing they read.
func printEnableNextEpilogue(w io.Writer, plan enableNextPlan, ident enableNextIdentity) {
	fmt.Fprintln(w)
	if plan.connect {
		fmt.Fprintf(w, "  Done. Entire is recording sessions for %s.\n", ident.label)
	} else {
		fmt.Fprintln(w, "  Done. Sessions are recorded in this repo.")
	}

	printEnableNextDecisions(w, plan)

	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Happy with these? Commit them and start your next agent session:")
	fmt.Fprintf(w, "    git add %s && git commit -m \"chore: configure entire\"\n", settings.EntireDirName)
	if plan.connect && ident.isGitHub() {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "  Your commits carry a trailer linking them back to the session that")
		fmt.Fprintln(w, "  produced them. Once you push, they show up on")
		fmt.Fprintf(w, "    %s\n", enableNextRepoWebURL(ident))
	}
	if !ident.hasOrigin {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "  Publish it when you are ready:")
		fmt.Fprintln(w, "    gh repo create --source=. --push")
	}
}
