cat > cmd/entire/cli/enable_next_plan.go <<'GOEOF'
package cli

import (
	"context"
	"fmt"
	"io"
	"net/url"
	"strings"

	"charm.land/huh/v2"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/uiform"
)

// enableNextPlan is every decision the flow made, in the order it prints them.
// It is one value rather than a handful of locals so the confirmation, the
// edit form, the apply step and the closing "chosen for you" block can never
// disagree about what was decided.
type enableNextPlan struct {
	// connect is the answer to the one question, after any degradation on the
	// connect path (see resolveEnableNextConnection).
	connect bool
	// region is the cluster the repository's session data lives in. Set only
	// when connect is true.
	region regionChoice
	// existingMirror records that region came from a placement that already
	// existed rather than one this run will create — the difference the plan
	// has to show, because only one of the two is a change.
	existingMirror bool
	agents         []types.AgentName
	// repointOrigin rewrites origin to the entire:// URL, so fetch and push
	// both flow through Entire and are forwarded to GitHub.
	repointOrigin bool
	telemetry     bool
	// githubOrigin records that the repository has a GitHub origin at all,
	// which is what makes the origin row meaningful.
	githubOrigin bool
}

// enableNextPlanRow is one label/value pair in the plan table.
type enableNextPlanRow struct {
	label string
	value string
	// change is the command that changes this decision later. Printed in the
	// closing summary, omitted from the pre-apply plan (where the edit path is
	// one keypress away and naming a command would be noise).
	change string
}

// enableNextPlanRows renders the plan as the rows both the confirmation and
// the closing summary print. Rows that would say nothing are left out rather
// than rendered as a dash: the origin row is meaningless without a GitHub
// origin, and the region row without an account.
func enableNextPlanRows(p enableNextPlan) []enableNextPlanRow {
	var rows []enableNextPlanRow

	if p.connect {
		note := "new mirror"
		if p.existingMirror {
			note = "existing mirror"
		}
		rows = append(rows, enableNextPlanRow{
			label:  "region",
			value:  fmt.Sprintf("%s  (%s)", enableNextRegionName(p.region), note),
			change: "entire repo mirror create",
		})
	}

	rows = append(rows, enableNextPlanRow{
		label:  "agents",
		value:  enableNextAgentLabel(p.agents),
		change: "entire agent add|remove <name>",
	})

	if p.connect && p.githubOrigin {
		value := "unchanged — stays on GitHub"
		if p.repointOrigin {
			value = "Entire (fetch and push, forwarded to GitHub)"
		}
		rows = append(rows, enableNextPlanRow{
			label:  "origin",
			value:  value,
			change: "entire repo mirror use",
		})
	}

	telemetry := "off"
	change := "entire configure --telemetry=true"
	if p.telemetry {
		telemetry = "on"
		change = "entire configure --telemetry=false"
	}
	rows = append(rows, enableNextPlanRow{label: "telemetry", value: telemetry, change: change})

	return rows
}

// enableNextRegionName is the region as a person would name it: the cluster
// slug, with the host as the fallback for a catalog entry that has none.
func enableNextRegionName(r regionChoice) string {
	if strings.TrimSpace(r.slug) != "" {
		return r.slug
	}
	return r.host
}

func enableNextAgentLabel(agents []types.AgentName) string {
	if len(agents) == 0 {
		return "none"
	}
	return strings.Join(agentDisplayNames(agents), ", ")
}

// printEnableNextPlan prints what the flow is about to do, ahead of the single
// confirming keypress.
func printEnableNextPlan(w io.Writer, p enableNextPlan) {
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Here is what Entire will do:")
	rows := enableNextPlanRows(p)
	width := 0
	for _, r := range rows {
		width = max(width, len(r.label))
	}
	for _, r := range rows {
		fmt.Fprintf(w, "    %-*s   %s\n", width, r.label, r.value)
	}
}

// printEnableNextDecisions prints the closing summary: the same decisions,
// each next to the command that changes it. This is what makes deciding
// instead of asking honest — every default is named, and nothing has to be
// discovered from documentation later.
func printEnableNextDecisions(w io.Writer, p enableNextPlan) {
	rows := enableNextPlanRows(p)
	labelWidth, valueWidth := 0, 0
	for _, r := range rows {
		labelWidth = max(labelWidth, len(r.label))
		valueWidth = max(valueWidth, len(r.value))
	}
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Chosen for you — change any of these:")
	for _, r := range rows {
		fmt.Fprintf(w, "    %-*s  %-*s   %s\n", labelWidth, r.label, valueWidth, r.value, r.change)
	}
}

// confirmEnableNextPlan runs the ending: print the plan, take one keypress,
// and offer the full form behind it with our answers already filled in.
// Reports whether to go ahead.
//
// --no-confirm is the other ending this command exists to compare: the plan is
// applied straight away and printed afterwards by the closing summary, which
// carries the same rows. A non-interactive run takes that path too — there is
// nobody to confirm to.
func confirmEnableNextPlan(ctx context.Context, outW, errW io.Writer, plan *enableNextPlan, conn *enableNextConnection, o enableNextOptions) (bool, error) {
	if o.noConfirm || !interactive.CanPromptInteractively() {
		return true, nil
	}
	for {
		printEnableNextPlan(outW, *plan)

		const (
			answerYes  = "yes"
			answerEdit = "edit"
		)
		answer := answerYes
		form := NewAccessibleForm(
			huh.NewGroup(
				huh.NewSelect[string]().
					Title(fmt.Sprintf("Ready to set up %s?", enableNextPlanSubject(*plan, conn))).
					Options(
						huh.NewOption("Yes, do it        —  press enter", answerYes),
						huh.NewOption("Change something  —  our answers preselected", answerEdit),
					).
					Value(&answer),
			),
		)
		if err := form.RunWithContext(ctx); err != nil {
			if cancelErr := handleFormCancellation(outW, "Setup", err); cancelErr != nil {
				return false, cancelErr
			}
			return false, nil
		}
		if answer == answerYes {
			return true, nil
		}
		edited, err := editEnableNextPlan(ctx, outW, errW, plan, conn)
		if err != nil {
			return false, err
		}
		if !edited {
			return false, nil
		}
	}
}

// enableNextPlanSubject names what is being set up in the confirmation title:
// the repository, which is also what the one question named.
func enableNextPlanSubject(p enableNextPlan, conn *enableNextConnection) string {
	if p.connect && conn != nil && conn.label != "" {
		return conn.label
	}
	return "this repository"
}

// editEnableNextPlan is the escape hatch behind the confirmation: every value
// the flow decided, asked in order, with the decided answer preselected. It
// exists so "we chose for you" is never a dead end. Reports false when the
// user cancelled out of it.
func editEnableNextPlan(ctx context.Context, outW, errW io.Writer, plan *enableNextPlan, conn *enableNextConnection) (bool, error) {
	if plan.connect && conn != nil && len(conn.regions) > 1 && !plan.existingMirror {
		ok, err := editEnableNextRegion(ctx, outW, plan, conn)
		if err != nil || !ok {
			return false, err
		}
	}
	if ok, err := editEnableNextAgents(ctx, outW, errW, plan); err != nil || !ok {
		return false, err
	}
	if plan.connect && plan.githubOrigin {
		if ok, err := editEnableNextOrigin(ctx, outW, plan); err != nil || !ok {
			return false, err
		}
	}
	return editEnableNextTelemetry(ctx, outW, plan)
}

func editEnableNextRegion(ctx context.Context, w io.Writer, plan *enableNextPlan, conn *enableNextConnection) (bool, error) {
	options := make([]huh.Option[string], 0, len(conn.regions))
	for _, r := range conn.regions {
		label := enableNextRegionName(r)
		if r.jurisdiction != "" {
			label = fmt.Sprintf("%s  (%s)", label, r.jurisdiction)
		}
		if r.host == plan.region.host {
			label += "   default — your login's home"
		}
		options = append(options, huh.NewOption(label, r.host))
	}
	host := plan.region.host
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Which region should this repo live in?").
				Description("Session history for this repository stays in the region you pick.").
				Options(options...).
				Value(&host),
		),
	)
	if err := form.RunWithContext(ctx); err != nil {
		if cancelErr := handleFormCancellation(w, "Setup", err); cancelErr != nil {
			return false, cancelErr
		}
		return false, nil
	}
	for _, r := range conn.regions {
		if r.host == host {
			plan.region = r
			break
		}
	}
	return true, nil
}

func editEnableNextAgents(ctx context.Context, outW, errW io.Writer, plan *enableNextPlan) (bool, error) {
	selectedSet := make(map[types.AgentName]struct{}, len(plan.agents))
	for _, name := range plan.agents {
		selectedSet[name] = struct{}{}
	}
	options := hookAgentOptions(selectedSet)
	if len(options) == 0 {
		return true, nil
	}
	selected := make([]string, 0, len(plan.agents))
	for _, name := range plan.agents {
		selected = append(selected, string(name))
	}
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewMultiSelect[string]().
				Title("Which agents should Entire capture?").
				Description("Space to select, enter to confirm.").
				Options(options...).
				Height(uiform.SingleLineMultiSelectHeight(len(options))).
				Value(&selected),
		),
	)
	if err := form.RunWithContext(ctx); err != nil {
		if cancelErr := handleFormCancellation(outW, "Setup", err); cancelErr != nil {
			return false, cancelErr
		}
		return false, nil
	}
	if len(selected) == 0 {
		// Zero agents captures nothing, which is not an answer this flow can
		// apply. Say so and keep what was already decided.
		fmt.Fprintln(errW, "  At least one agent is needed to capture sessions — keeping the detected ones.")
		return true, nil
	}
	names, err := enableNextAgentNames(selected)
	if err != nil {
		return false, err
	}
	plan.agents = names
	return true, nil
}

func editEnableNextOrigin(ctx context.Context, w io.Writer, plan *enableNextPlan) (bool, error) {
	const (
		originEntire = "entire"
		originGitHub = "github"
	)
	choice := originGitHub
	if plan.repointOrigin {
		choice = originEntire
	}
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Where should this repo's pushes go?").
				Options(
					huh.NewOption("Entire  —  one remote, both directions · forwarded to GitHub   default", originEntire),
					huh.NewOption("GitHub  —  leave origin alone · checkpoints still sync", originGitHub),
				).
				Value(&choice),
		),
	)
	if err := form.RunWithContext(ctx); err != nil {
		if cancelErr := handleFormCancellation(w, "Setup", err); cancelErr != nil {
			return false, cancelErr
		}
		return false, nil
	}
	plan.repointOrigin = choice == originEntire
	return true, nil
}

func editEnableNextTelemetry(ctx context.Context, w io.Writer, plan *enableNextPlan) (bool, error) {
	telemetry := plan.telemetry
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Share anonymous usage data?").
				Description("No code, prompts, or personal information.").
				Affirmative("Yes").
				Negative("No").
				Value(&telemetry),
		),
	)
	if err := form.RunWithContext(ctx); err != nil {
		if cancelErr := handleFormCancellation(w, "Setup", err); cancelErr != nil {
			return false, cancelErr
		}
		return false, nil
	}
	plan.telemetry = telemetry
	return true, nil
}

// enableNextRepoWebURL is where this repository's sessions show up on the web.
// Built from the same origin the rest of the CLI's user-facing links use, so a
// dev frontend (ENTIRE_WEB_BASE_URL) is honoured here too.
func enableNextRepoWebURL(ident enableNextIdentity) string {
	if !ident.isGitHub() {
		return ""
	}
	return fmt.Sprintf("%s/gh/%s/%s", expertsWebBaseURL(), url.PathEscape(ident.owner), url.PathEscape(ident.repo))
}

// enableNextAPIBase is only referenced to keep the api import honest when the
// web-URL helper is the sole consumer of the package in this file.
var _ = api.DefaultBaseURL
