	"github.com/entireio/cli/internal/coreapi"
)

const (
	// enableNextAccessPollInterval and enableNextAccessWaitTimeout bound the
	// wait for a GitHub App installation the user is performing in a browser.
	// The wait is generous because a repository admin may have to find the
	// right organization first — but it is bounded, because the flow has a
	// working answer (capture only) to fall back on.
	enableNextAccessPollInterval = 2 * time.Second
	enableNextAccessWaitTimeout  = 5 * time.Minute
	// enableNextAccessMaxErrors is how many consecutive failed access probes
	// end the wait. A single transient error while someone is clicking through
	// GitHub is not a reason to give up.
	enableNextAccessMaxErrors = 3
	// enableNextMirrorTimeout bounds waiting for a new mirror's initial clone.
	enableNextMirrorTimeout = 30 * time.Minute
)

// enableNextAccessReporter is the slice of the authenticated API the connect
// path uses: one call that records the enable and reports whether the GitHub
// App can currently reach the repository. Narrow on purpose, so the
// access-and-degrade state machine is testable without a live backend.
type enableNextAccessReporter interface {
	ReportEnable(ctx context.Context, remoteURL string) (*api.EnableRepoResponse, error)
}

// enableNextDeps are the side effects the flow performs. Injected so the whole
// flow can be tested without a keyring, a browser, the gh CLI, a control plane
// or a real git repository.
type enableNextDeps struct {
	resolveAuth  func(context.Context) (statusTarget, error)
	fetchProfile profileFetcher
	runLogin     func(ctx context.Context, outW, errW io.Writer) error
	accessClient func(context.Context) (enableNextAccessReporter, error)
	coreClient   func() (*coreapi.Client, error)
	// clusterClient dials the core fronting a specific cluster, which is what
	// mirror creation is addressed at (see runCoreForCluster).
	clusterClient func(ctx context.Context, clusterHost string) (*coreapi.Client, error)
	openURL       browserOpenFunc
	githubAdmin   func(ctx context.Context, owner, repo string) (bool, error)
	confirmInit   func(ctx context.Context, dir string) (bool, error)
	runner        bootstrapRunner
}

func newEnableNextDeps(insecureHTTP bool) enableNextDeps {
	return enableNextDeps{
		resolveAuth: func(ctx context.Context) (statusTarget, error) {
			return resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
		},
		fetchProfile: defaultFetchProfile,
		runLogin: func(ctx context.Context, outW, errW io.Writer) error {
			cmd := newLoginCmd()
			cmd.SetContext(ctx)
			cmd.SetOut(outW)
			cmd.SetErr(errW)
			return cmd.RunE(cmd, nil)
		},
		accessClient: func(ctx context.Context) (enableNextAccessReporter, error) {
			return NewAuthenticatedAPIClient(ctx, insecureHTTP)
		},
		coreClient:    coreapi.New,
		clusterClient: clusterCoreClient,
		openURL:       openBrowser,
		githubAdmin:   configureGitHubAdmin,
		confirmInit: func(ctx context.Context, dir string) (bool, error) {
			return uiform.PromptYN(ctx, fmt.Sprintf("No git repository in %q. Initialize one?", dir), true)
		},
		runner: execRunner{},
	}
}

// enableNextConnection is what the connect path resolved: the account, the
// region the repository's data lives in, and the regions the region question
// would offer if the user opens the edit form.
type enableNextConnection struct {
	// label is the repository as the account knows it (owner/repo).
	label string
	// handle is the signed-in account.
	handle string
	// region is the placement to use: an existing one when the repository is
	// already mirrored, otherwise the one this run will create.
	region regionChoice
	// existing distinguishes the two, because only one of them is a change.
	existing bool
	// regions is the cluster catalog, for the region question in the edit
	// form. Empty when the catalog could not be read, which only costs the
	// question, not the flow.
	regions []regionChoice
}

// resolveEnableNextConnection does everything the "Connect to Entire" answer
// needs before anything is applied: sign in, confirm the GitHub App can reach
// the repository, and work out which region the data lives in.
//
// It returns (nil, nil) when the repository cannot be connected — no GitHub
// origin, an App nobody has installed yet, an unreachable control plane. That
// is not an error: session capture works without an account, so the flow
// degrades to the local answer with a message naming what to do about it,
// rather than exiting and leaving the user with nothing. This is the single
// biggest behavioural difference from today's flow, where four of the seven
// known failure paths end the command.
func resolveEnableNextConnection(ctx context.Context, outW, errW io.Writer, ident enableNextIdentity, o enableNextOptions, deps enableNextDeps) (*enableNextConnection, error) {
	if !ident.isGitHub() {
		// Hosting a repository on Entire natively needs a repository on the
		// control plane to host it, which is its own (project-scoped)
		// operation. Name it, and keep going with capture.
		fmt.Fprintln(errW, "  ✗ No GitHub origin, so there is nothing to mirror yet")
		fmt.Fprintf(errW, "    Create the repo on Entire:  entire repo create %s --project <project>\n", ident.label)
		fmt.Fprintln(errW, "    or publish it to GitHub:    gh repo create --source=. --push")
		fmt.Fprintln(errW, "    Then run `entire enable-next` again to connect it.")
		fmt.Fprintln(errW, "  Continuing with capture only.")
		return nil, nil
	}

	profile, err := ensureEnableNextLogin(ctx, outW, errW, deps)
	if err != nil {
		return nil, err
	}
	if profile == nil {
		return nil, nil
	}

	reporter, err := deps.accessClient(ctx)
	if err != nil {
		return nil, enableNextDegrade(errW, "could not reach Entire", err)
	}
	if !enableNextEnsureAccess(ctx, outW, errW, reporter, ident, o, deps) {
		return nil, nil
	}

	client, err := deps.coreClient()
	if err != nil {
		return nil, enableNextDegrade(errW, "could not reach Entire's control plane", err)
	}

	conn := &enableNextConnection{label: ident.fullName(), handle: profile.Handle}

	// An existing placement decides the region: a second person joining a
	// repository their team already onboarded gets that team's region, not
	// their own default.
	placements, err := resolvePullablePlacements(ctx, client, ident.owner, ident.repo)
	if err != nil {
		return nil, enableNextDegrade(errW, "could not look up this repository on Entire", err)
	}
	conn.regions = enableNextRegions(ctx, outW, client)

	if placement, ok := enableNextExistingPlacement(placements, o.region); ok {
		conn.region = enableNextRegionFor(placement, conn.regions)
		conn.existing = true
		fmt.Fprintf(outW, "  ✓ Mirror already exists       %s\n", enableNextRegionName(conn.region))
		return conn, nil
	}

	region, err := enableNextTargetRegion(conn.regions, profile.Jurisdiction, o.region)
	if err != nil {
		return nil, enableNextDegrade(errW, "could not pick a region for this repository", err)
	}
	conn.region = region
	fmt.Fprintf(outW, "  ✗ Not mirrored yet — one will be created in %s\n", enableNextRegionName(region))
	return conn, nil
}

// enableNextDegrade reports why the connect path stopped and returns no error,
// so the caller falls back to the local answer. The reason is logged at debug
// with the underlying error; the user gets the sentence, not the stack.
func enableNextDegrade(errW io.Writer, what string, cause error) error {
	fmt.Fprintf(errW, "  ✗ %s: %v\n", what, cause)
	fmt.Fprintln(errW, "  Continuing with capture only — rerun `entire enable-next` to connect.")
	return nil
}

// ensureEnableNextLogin resolves the account, logging in when there is no
// usable session. Returns (nil, nil) when signing in was not possible, which
// degrades the flow to the local answer.
func ensureEnableNextLogin(ctx context.Context, outW, errW io.Writer, deps enableNextDeps) (*authProfile, error) {
	target, err := deps.resolveAuth(ctx)
	if err == nil && target.token != "" {
		if secErr := api.RequireSecureURL(target.coreURL); secErr != nil {
			return nil, enableNextDegradeProfile(errW, "login server is not usable", secErr)
		}
		profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token)
		if profileErr == nil {
			fmt.Fprintf(outW, "  ✓ Signed in as %s   (existing session)\n", profile.Handle)
			return profile, nil
		}
		if !isKeychainTokenRejected(profileErr) {
			return nil, enableNextDegradeProfile(errW, "could not validate your login", profileErr)
		}
		logging.Debug(ctx, "enable-next: stored login rejected, logging in again", "error", profileErr)
	}

	if !interactive.CanPromptInteractively() {
		fmt.Fprintln(errW, "  ✗ Not signed in, and there is no terminal to sign in from")
		fmt.Fprintln(errW, "    Run `entire login` (or `entire login --device`), then rerun this command.")
		fmt.Fprintln(errW, "  Continuing with capture only.")
		return nil, nil
	}
	if err := deps.runLogin(ctx, outW, errW); err != nil {
		return nil, enableNextDegradeProfile(errW, "login did not complete", err)
	}
	target, err = deps.resolveAuth(ctx)
	if err != nil {
		return nil, enableNextDegradeProfile(errW, "could not read the new login", err)
	}
	if target.token == "" {
		return nil, enableNextDegradeProfile(errW, "login completed without an active session", errors.New("no token"))
	}
	if err := api.RequireSecureURL(target.coreURL); err != nil {
		return nil, enableNextDegradeProfile(errW, "login server is not usable", err)
	}
	profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
	if err != nil {
		return nil, enableNextDegradeProfile(errW, "could not validate your login", err)
	}
	fmt.Fprintf(outW, "  ✓ Signed in as %s\n", profile.Handle)
	return profile, nil
}

// enableNextDegradeProfile is enableNextDegrade for the login step, whose
// caller returns a profile rather than a connection.
func enableNextDegradeProfile(errW io.Writer, what string, cause error) error {
	return enableNextDegrade(errW, what, cause)
}

// enableNextEnsureAccess confirms the GitHub App can reach the repository,
// guiding an installation when it cannot. Reports whether the connect path may
// continue.
//
// Not being a repository admin no longer ends the command: the link goes to
// whoever can install it and this run lands on the local answer. That single
// change is what makes "capture works either way" true in practice.
func enableNextEnsureAccess(ctx context.Context, outW, errW io.Writer, reporter enableNextAccessReporter, ident enableNextIdentity, o enableNextOptions, deps enableNextDeps) bool {
	access, err := reporter.ReportEnable(ctx, ident.cleanRemote)
	if err != nil {
		_ = enableNextDegrade(errW, "could not check Entire's access to "+ident.fullName(), err)
		return false
	}
	if access.Connected {
		fmt.Fprintf(outW, "  ✓ Entire has access to %s\n", ident.fullName())
		return true
	}

	fmt.Fprintf(errW, "  ✗ Entire has no access to %s\n", ident.fullName())
	installURL := strings.TrimSpace(access.InstallURL)
	if installURL == "" {
		fmt.Fprintln(errW, "    Entire did not return a GitHub App installation URL — try again later.")
		fmt.Fprintln(errW, "  Continuing with capture only.")
		return false
	}

	admin, adminErr := deps.githubAdmin(ctx, ident.owner, ident.repo)
	switch {
	case adminErr == nil && !admin:
		fmt.Fprintln(errW, "    An admin needs to install the GitHub App. Send them this link:")
		fmt.Fprintf(errW, "      %s\n", installURL)
		fmt.Fprintln(errW, "  Continuing with capture only — capture works either way.")
		return false
	case adminErr != nil:
		// Whether the user administers the repository is unknown (no gh CLI,
		// not authenticated, API error). Offer the link rather than assuming
		// either answer; they can act on it if it is theirs to install.
		logging.Debug(ctx, "enable-next: GitHub admin check unavailable", "error", adminErr)
	}

	fmt.Fprintln(outW, "    Install the GitHub App to grant access:")
	fmt.Fprintf(outW, "      %s\n", installURL)
	if o.yes || !interactive.CanPromptInteractively() {
		fmt.Fprintln(errW, "  Continuing with capture only — rerun `entire enable-next` once it is installed.")
		return false
	}
	if err := deps.openURL(ctx, installURL); err != nil {
		fmt.Fprintln(outW, "    Open the link above in your browser.")
	}

	stop := startSpinner(errW, "Waiting for the installation")
	waitCtx, cancel := context.WithTimeout(ctx, enableNextAccessWaitTimeout)
	defer cancel()
	waitErr := waitForEnableNextAccess(waitCtx, reporter, ident.cleanRemote, enableNextAccessPollInterval, enableNextAccessMaxErrors)
	stop(waitErr == nil)
	if waitErr != nil {
		_ = enableNextDegrade(errW, "the GitHub App is still not installed", waitErr)
		return false
	}
	fmt.Fprintln(outW, "  ✓ Access granted")
	return true
}

// waitForEnableNextAccess polls until the App can reach the repository, the
// deadline passes, or the probe fails maxErrors times in a row.
func waitForEnableNextAccess(ctx context.Context, reporter enableNextAccessReporter, cleanRemote string, pollInterval time.Duration, maxErrors int) error {
	ticker := time.NewTicker(pollInterval)
	defer ticker.Stop()
	consecutiveErrors := 0
	for {
		select {
		case <-ctx.Done():
			return fmt.Errorf("waiting for the GitHub App installation: %w", ctx.Err())
		case <-ticker.C:
			access, err := reporter.ReportEnable(ctx, cleanRemote)
			if err != nil {
				consecutiveErrors++
				if consecutiveErrors >= maxErrors {
					return fmt.Errorf("checking repository access: %w", err)
				}
				continue
			}
			consecutiveErrors = 0
			if access != nil && access.Connected {
				return nil
			}
		}
	}
}

// enableNextRegions reads the cluster catalog. Best-effort: without it the
// region question in the edit form has nothing to offer, which costs the
// question and not the flow.
func enableNextRegions(ctx context.Context, outW io.Writer, client *coreapi.Client) []regionChoice {
	regions, err := availableRegions(ctx, client)
	if err != nil {
		logging.Debug(ctx, "enable-next: cluster catalog unavailable", "error", err)
		return nil
	}
	_ = outW
	return regions
}

// enableNextExistingPlacement picks the placement to adopt from those the
// repository already has. An explicit --region wins when it names one of them;
// otherwise the first placement the control plane returned is used, which is
// the same order `repo clone` offers.
func enableNextExistingPlacement(placements []coreapi.ResolvedPlacement, regionSel string) (coreapi.ResolvedPlacement, bool) {
	if len(placements) == 0 {
		return coreapi.ResolvedPlacement{}, false
	}
	if sel := strings.TrimSpace(regionSel); sel != "" {
		for _, p := range placements {
			if enableNextRegionMatches(sel, p.ClusterHost, p.Cell.Or("")) {
				return p, true
			}
		}
	}
	return placements[0], true
}

// enableNextRegionFor names an existing placement in the catalog's terms, so
// the plan shows a slug rather than a bare host when the catalog knows one.
func enableNextRegionFor(placement coreapi.ResolvedPlacement, regions []regionChoice) regionChoice {
	for _, r := range regions {
		if strings.EqualFold(r.host, placement.ClusterHost) {
			return r
		}
	}
	return regionChoice{
		slug:         placement.Cell.Or(""),
		jurisdiction: placement.Jurisdiction.Or(""),
		host:         placement.ClusterHost,
	}
}

// enableNextTargetRegion is the region decision for a repository with no
// mirror yet: an explicit --region, else the default cluster of the login's
// home jurisdiction — which is the whole point of not asking. Falls back to
// the fixed default cluster when the catalog is unreadable, so an offline
// catalog does not cost the connect path.
func enableNextTargetRegion(regions []regionChoice, jurisdiction, regionSel string) (regionChoice, error) {
	if sel := strings.TrimSpace(regionSel); sel != "" {
		for _, r := range regions {
			if enableNextRegionMatches(sel, r.host, r.slug) {
				return r, nil
			}
		}
		if len(regions) == 0 {
			// No catalog to validate against; trust the caller's host and let
			// the create call reject it if it is wrong.
			if err := validateClusterHost(sel); err != nil {
				return regionChoice{}, fmt.Errorf("invalid --region %q: %w", sel, err)
			}
			return regionChoice{host: sel}, nil
		}
		return regionChoice{}, fmt.Errorf("no region matches --region %q", sel)
	}
	if len(regions) == 0 {
		return regionChoice{host: defaultClusterHost}, nil
	}
	_, defaults := clusterChoices(regions, jurisdiction)
	for _, host := range defaults {
		for _, r := range regions {
			if r.host == host {
				return r, nil
			}
		}
	}
	// No jurisdiction default (an account whose home jurisdiction the catalog
	// does not cover): the catalog's own default is the next best answer.
	for _, r := range regions {
		if r.isDefault {
			return r, nil
		}
	}
	return regions[0], nil
}

// enableNextRegionMatches compares a user-supplied region selector against a
// cluster's host and slug, so `--region eu-central-1` and
// `--region aws-eu-central-1.entire.io` both work.
func enableNextRegionMatches(sel, host, slug string) bool {
	sel = strings.TrimSpace(sel)
	return strings.EqualFold(sel, host) || (slug != "" && strings.EqualFold(sel, slug))
}

// applyEnableNextConnection performs the connect path's writes: create the
// mirror if it does not exist, then point origin through Entire. Both are
// printed as they happen, in the order they happen.
func applyEnableNextConnection(ctx context.Context, outW, errW io.Writer, ident enableNextIdentity, plan enableNextPlan, conn *enableNextConnection, deps enableNextDeps) error {
	if !plan.existingMirror {
		if err := createEnableNextMirror(ctx, outW, errW, ident, plan, deps); err != nil {
			return err
		}
	} else {
		fmt.Fprintf(outW, "  ✓ Region %-16s  (mirror already existed)\n", enableNextRegionName(plan.region))
	}
	if !plan.repointOrigin {
		fmt.Fprintln(outW, "  ✓ origin unchanged                (checkpoints still sync through it)")
		return nil
	}
	return repointEnableNextOrigin(ctx, outW, ident, plan)
}

// createEnableNextMirror registers the repository's mirror and waits for its
// initial clone, so the entire:// remote works by the time the flow points
// origin at it.
func createEnableNextMirror(ctx context.Context, outW, errW io.Writer, ident enableNextIdentity, plan enableNextPlan, deps enableNextDeps) error {
	client, err := deps.clusterClient(ctx, plan.region.host)
	if err != nil {
		return fmt.Errorf("connect to the control plane for %s: %w", plan.region.host, err)
	}
	opts := mirrorCreateOptions{timeout: enableNextMirrorTimeout}
	var finishPhase func(bool)
	opts.onPhase = func(next mirrorCreatePhase) {
		if finishPhase != nil {
			finishPhase(true)
		}
		finishPhase = startSpinner(errW, fmt.Sprintf("%s mirror %s into %s", next.label(), ident.fullName(), enableNextRegionName(plan.region)))
	}
	outcome, err := createAndAwaitMirror(ctx, client, ident.owner, ident.repo, plan.region.host, opts)
	if finishPhase != nil {
		finishPhase(err == nil)
	}
	if err != nil {
		return renderCoreError(err)
	}
	if outcome.created != nil && !outcome.created.Created {
		fmt.Fprintf(outW, "  ✓ Region %-16s  (mirror already existed)\n", enableNextRegionName(plan.region))
		return nil
	}
	fmt.Fprintf(outW, "  ✓ Created mirror %-8s  (%s)\n", enableNextRegionName(plan.region), enableNextJurisdictionLabel(plan.region))
	return nil
}

func enableNextJurisdictionLabel(r regionChoice) string {
	if strings.TrimSpace(r.jurisdiction) != "" {
		return r.jurisdiction
	}
	return r.host
}

// repointEnableNextOrigin makes origin the entire:// URL: one remote, one URL,
// fetch and push both flowing through Entire, which forwards to GitHub.
// Nothing is added alongside it and the previous URL is not parked under a
// second remote — the whole point of this shape is that there is only one.
func repointEnableNextOrigin(ctx context.Context, w io.Writer, ident enableNextIdentity, plan enableNextPlan) error {
	remotes, err := listGitRemotes(ctx, ident.root)
	if err != nil {
		return err
	}
	mirrorURL := mirrorCloneURL(plan.region.host, ident.owner, ident.repo)
	remotePlan := planMirrorRemote(defaultMirrorRemote, mirrorURL, ident.originURL, "", remotes)
	if remotePlan.noop {
		fmt.Fprintln(w, "  ✓ origin → Entire                 (already pointed there)")
		return nil
	}
	if err := applyMirrorRemotePlan(ctx, ident.root, remotePlan); err != nil {
		return err
	}
	fmt.Fprintln(w, "  ✓ origin → Entire                 (fetch and push, forwarded to GitHub)")
	if remotePlan.replacedURL != "" {
		fmt.Fprintf(w, "    was: %s\n", gitremote.RedactURL(remotePlan.replacedURL))
	}
	return nil
}
