	region    func(regions []regionChoice, current regionChoice) (string, bool, error)
	agents    func(options []huh.Option[string], selected []string) ([]string, bool, error)
	origin    func(repoint bool) (bool, bool, error)
	telemetry func(current bool) (bool, bool, error)
}

func (s stubEnableNextPrompts) install(t *testing.T) {
	t.Helper()

	prevQuestion := enableNextQuestionPrompt
	prevConfirm := enableNextConfirmPrompt
	prevRegion := enableNextRegionPrompt
	prevAgents := enableNextAgentsPrompt
	prevOrigin := enableNextOriginPrompt
	prevTelemetry := enableNextTelemetryPrompt
	t.Cleanup(func() {
		enableNextQuestionPrompt = prevQuestion
		enableNextConfirmPrompt = prevConfirm
		enableNextRegionPrompt = prevRegion
		enableNextAgentsPrompt = prevAgents
		enableNextOriginPrompt = prevOrigin
		enableNextTelemetryPrompt = prevTelemetry
	})

	enableNextQuestionPrompt = func(_ context.Context, _ io.Writer, ident enableNextIdentity) (string, bool, error) {
		if s.question == nil {
			t.Fatal("the one question was asked, but the test supplied no answer")
		}
		return s.question(ident)
	}
	enableNextConfirmPrompt = func(_ context.Context, _ io.Writer, subject string) (string, bool, error) {
		if s.confirm == nil {
			t.Fatal("the confirmation was shown, but the test supplied no answer")
		}
		return s.confirm(subject)
	}
	enableNextRegionPrompt = func(_ context.Context, _ io.Writer, regions []regionChoice, current regionChoice) (string, bool, error) {
		if s.region == nil {
			t.Fatal("the region question was asked, but the test supplied no answer")
		}
		return s.region(regions, current)
	}
	enableNextAgentsPrompt = func(_ context.Context, _ io.Writer, options []huh.Option[string], selected []string) ([]string, bool, error) {
		if s.agents == nil {
			t.Fatal("the agent checklist was shown, but the test supplied no answer")
		}
		return s.agents(options, selected)
	}
	enableNextOriginPrompt = func(_ context.Context, _ io.Writer, repoint bool) (bool, bool, error) {
		if s.origin == nil {
			t.Fatal("the origin question was asked, but the test supplied no answer")
		}
		return s.origin(repoint)
	}
	enableNextTelemetryPrompt = func(_ context.Context, _ io.Writer, current bool) (bool, bool, error) {
		if s.telemetry == nil {
			t.Fatal("the telemetry question was asked, but the test supplied no answer")
		}
		return s.telemetry(current)
	}
}

// TestAskEnableNextQuestion_FlagsAnswerIt pins that the one question has a
// non-interactive door in both directions. An agent or CI job must be able to
// run the whole flow, and connecting — which signs in and rewrites origin —
// must never be assumed on its behalf.
func TestAskEnableNextQuestion_FlagsAnswerIt(t *testing.T) {
	t.Parallel()

	ident := enableNextIdentity{label: "acme/widget", owner: "acme", repo: "widget"}

	t.Run("--connect", func(t *testing.T) {
		t.Parallel()
		var out bytes.Buffer
		got, err := askEnableNextQuestion(context.Background(), &out, ident, enableNextOptions{connect: true})
		if err != nil || got != enableNextAnswerConnect {
			t.Fatalf("askEnableNextQuestion() = %q, %v; want %q, nil", got, err, enableNextAnswerConnect)
		}
	})

	t.Run("--local-only", func(t *testing.T) {
		t.Parallel()
		var out bytes.Buffer
		got, err := askEnableNextQuestion(context.Background(), &out, ident, enableNextOptions{localOnly: true})
		if err != nil || got != enableNextAnswerLocal {
			t.Fatalf("askEnableNextQuestion() = %q, %v; want %q, nil", got, err, enableNextAnswerLocal)
		}
	})

	// Unanswered without a terminal is a refusal that names both flags, not a
	// silent default into either answer.
	t.Run("unanswered without a terminal", func(t *testing.T) {
		t.Parallel()
		var out bytes.Buffer
		_, err := askEnableNextQuestion(context.Background(), &out, ident, enableNextOptions{})
		if err == nil {
			t.Fatal("askEnableNextQuestion() error = nil, want a refusal")
		}
		var silent *SilentError
		if !errors.As(err, &silent) {
			t.Errorf("error = %T, want SilentError (the message is already printed)", err)
		}
		for _, want := range []string{"--connect", "--local-only"} {
			if !strings.Contains(out.String(), want) {
				t.Errorf("output must name %s, got:\n%s", want, out.String())
			}
		}
	})
}

