func TestEnableNextPlanRows(t *testing.T) {
	t.Parallel()

	region := regionChoice{slug: "eu-central-1", jurisdiction: "eu", host: "aws-eu-central-1.entire.io"}
	agents := []types.AgentName{types.AgentName("claude-code")}

	tests := []struct {
		name     string
		plan     enableNextPlan
		want     map[string]string
		notThere []string
	}{
		{
			name: "connecting with a new mirror",
			plan: enableNextPlan{connect: true, region: region, agents: agents, repointOrigin: true, telemetry: true, githubOrigin: true},
			want: map[string]string{
				"region":    "eu-central-1  (new mirror)",
				"origin":    "Entire (fetch and push, forwarded to GitHub)",
				"telemetry": "on",
			},
		},
		{
			name: "an existing mirror is not a change",
			plan: enableNextPlan{connect: true, region: region, existingMirror: true, agents: agents, repointOrigin: true, telemetry: true, githubOrigin: true},
			want: map[string]string{"region": "eu-central-1  (existing mirror)"},
		},
		{
			name: "keeping origin on GitHub",
			plan: enableNextPlan{connect: true, region: region, agents: agents, telemetry: false, githubOrigin: true},
			want: map[string]string{
				"origin":    "unchanged — stays on GitHub",
				"telemetry": "off",
			},
		},
		{
			// The local answer has no region and no origin rewrite, so those
			// rows are absent rather than rendered as a dash.
			name:     "just my repo",
			plan:     enableNextPlan{agents: agents, telemetry: true, githubOrigin: true},
			want:     map[string]string{"agents": "Claude Code", "telemetry": "on"},
			notThere: []string{"region", "origin"},
		},
		{
			// Connected, but with no GitHub origin there is nothing to say
			// about origin.
			name:     "connected without a GitHub origin",
			plan:     enableNextPlan{connect: true, region: region, agents: agents, telemetry: true},
			want:     map[string]string{"region": "eu-central-1  (new mirror)"},
			notThere: []string{"origin"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got := make(map[string]string)
			for _, row := range enableNextPlanRows(tt.plan) {
				got[row.label] = row.value
			}
			for label, want := range tt.want {
				if got[label] != want {
					t.Errorf("row %q = %q, want %q", label, got[label], want)
				}
			}
			for _, label := range tt.notThere {
				if _, ok := got[label]; ok {
					t.Errorf("row %q should not be rendered for this plan (got %q)", label, got[label])
				}
			}
		})
	}
}

// TestEnableNextPlanRows_EveryRowNamesItsCommand is the point of deciding
// instead of asking: a default the user cannot find the switch for is just a
// hidden decision. Every row carries the command that changes it, and the
// telemetry row's command points at the opposite of the current value.
func TestEnableNextPlanRows_EveryRowNamesItsCommand(t *testing.T) {
	t.Parallel()

	plan := enableNextPlan{
		connect:       true,
		region:        regionChoice{slug: "eu-central-1", host: "aws-eu-central-1.entire.io"},
		agents:        []types.AgentName{types.AgentName("claude-code")},
		repointOrigin: true,
		telemetry:     true,
		githubOrigin:  true,
	}
	for _, row := range enableNextPlanRows(plan) {
		if strings.TrimSpace(row.change) == "" {
			t.Errorf("row %q carries no command to change it", row.label)
		}
		if !strings.HasPrefix(row.change, "entire ") {
			t.Errorf("row %q change = %q, want a runnable `entire` command", row.label, row.change)
		}
	}

	var out bytes.Buffer
	printEnableNextDecisions(&out, plan)
	if !strings.Contains(out.String(), "--telemetry=false") {
		t.Errorf("telemetry is on, so the command must turn it off; got:\n%s", out.String())
	}
	plan.telemetry = false
	out.Reset()
	printEnableNextDecisions(&out, plan)
	if !strings.Contains(out.String(), "--telemetry=true") {
		t.Errorf("telemetry is off, so the command must turn it on; got:\n%s", out.String())
	}
}

func TestConfirmEnableNextPlan(t *testing.T) {
	basePlan := func() enableNextPlan {
		return enableNextPlan{
			connect:       true,
			region:        regionChoice{slug: "eu-central-1", host: "aws-eu-central-1.entire.io"},
			agents:        []types.AgentName{types.AgentName("claude-code")},
			repointOrigin: true,
			telemetry:     true,
			githubOrigin:  true,
		}
	}

	// --no-confirm is the second of the two endings: no plan, no keypress.
	t.Run("--no-confirm applies directly", func(t *testing.T) {
		t.Setenv("ENTIRE_TEST_TTY", "1")
		stubEnableNextPrompts{}.install(t) // any prompt here fails the test
		var out bytes.Buffer
		plan := basePlan()
		ok, err := confirmEnableNextPlan(context.Background(), &out, &out, &plan, nil, enableNextOptions{noConfirm: true})
		if err != nil || !ok {
			t.Fatalf("confirmEnableNextPlan() = %v, %v; want true, nil", ok, err)
		}
		if out.Len() != 0 {
			t.Errorf("nothing should be printed before applying, got:\n%s", out.String())
		}
	})

	t.Run("one keypress applies", func(t *testing.T) {
		t.Setenv("ENTIRE_TEST_TTY", "1")
		stubEnableNextPrompts{confirm: func(string) (string, bool, error) {
			return enableNextConfirmYes, true, nil
		}}.install(t)
		var out bytes.Buffer
		plan := basePlan()
		ok, err := confirmEnableNextPlan(context.Background(), &out, &out, &plan, nil, enableNextOptions{})
		if err != nil || !ok {
			t.Fatalf("confirmEnableNextPlan() = %v, %v; want true, nil", ok, err)
		}
		if !strings.Contains(out.String(), "Here is what Entire will do:") {
			t.Errorf("the plan must be shown before the keypress, got:\n%s", out.String())
		}
	})

	// "Change something…" is the escape hatch behind the confirmation: every
	// decided value asked, then back to the plan — which must now show the
	// edits.
	t.Run("editing every value, then confirming", func(t *testing.T) {
		t.Setenv("ENTIRE_TEST_TTY", "1")
		confirms := 0
		conn := &enableNextConnection{
			label: "acme/widget",
			regions: []regionChoice{
				{slug: "eu-central-1", host: "aws-eu-central-1.entire.io"},
				{slug: "us-east-2", host: "aws-us-east-2.entire.io"},
			},
		}
		stubEnableNextPrompts{
			confirm: func(subject string) (string, bool, error) {
				confirms++
				if subject != "acme/widget" {
					t.Errorf("confirmation subject = %q, want acme/widget", subject)
				}
				if confirms == 1 {
					return enableNextConfirmEdit, true, nil
				}
				return enableNextConfirmYes, true, nil
			},
			region: func(regions []regionChoice, current regionChoice) (string, bool, error) {
				if current.slug != "eu-central-1" {
					t.Errorf("region question preselected %q, want the decided eu-central-1", current.slug)
				}
				return "aws-us-east-2.entire.io", true, nil
			},
			agents: func(_ []huh.Option[string], selected []string) ([]string, bool, error) {
				if len(selected) != 1 || selected[0] != "claude-code" {
					t.Errorf("agent checklist preselected %v, want [claude-code]", selected)
				}
				return []string{"claude-code"}, true, nil
			},
			origin: func(repoint bool) (bool, bool, error) {
				if !repoint {
					t.Error("origin question must preselect the decided repoint")
				}
				return false, true, nil
			},
			telemetry: func(current bool) (bool, bool, error) {
				if !current {
					t.Error("telemetry question must preselect the decided value")
				}
				return false, true, nil
			},
		}.install(t)

		var out bytes.Buffer
		plan := basePlan()
		ok, err := confirmEnableNextPlan(context.Background(), &out, &out, &plan, conn, enableNextOptions{})
		if err != nil || !ok {
			t.Fatalf("confirmEnableNextPlan() = %v, %v; want true, nil", ok, err)
		}
		if confirms != 2 {
			t.Errorf("confirmation shown %d times, want 2 (before and after editing)", confirms)
		}
		if plan.region.slug != "us-east-2" {
			t.Errorf("plan.region = %q, want the edited us-east-2", plan.region.slug)
		}
		if plan.repointOrigin {
			t.Error("plan.repointOrigin = true, want the edited false")
		}
		if plan.telemetry {
			t.Error("plan.telemetry = true, want the edited false")
		}
	})

	// An existing mirror is not ours to move, so the region question is not
	// offered for one.
	t.Run("no region question for an existing mirror", func(t *testing.T) {
		t.Setenv("ENTIRE_TEST_TTY", "1")
		confirms := 0
		conn := &enableNextConnection{
			label:   "acme/widget",
			regions: []regionChoice{{slug: "eu-central-1", host: "a.entire.io"}, {slug: "us-east-2", host: "b.entire.io"}},
		}
		stubEnableNextPrompts{
			confirm: func(string) (string, bool, error) {
				confirms++
				if confirms == 1 {
					return enableNextConfirmEdit, true, nil
				}
				return enableNextConfirmYes, true, nil
			},
			// region is deliberately unset: reaching it fails the test.
			agents:    func(_ []huh.Option[string], sel []string) ([]string, bool, error) { return sel, true, nil },
			origin:    func(repoint bool) (bool, bool, error) { return repoint, true, nil },
			telemetry: func(current bool) (bool, bool, error) { return current, true, nil },
		}.install(t)

		var out bytes.Buffer
		plan := basePlan()
		plan.existingMirror = true
		if ok, err := confirmEnableNextPlan(context.Background(), &out, &out, &plan, conn, enableNextOptions{}); err != nil || !ok {
			t.Fatalf("confirmEnableNextPlan() = %v, %v; want true, nil", ok, err)
		}
	})

	t.Run("cancelling writes nothing", func(t *testing.T) {
		t.Setenv("ENTIRE_TEST_TTY", "1")
		stubEnableNextPrompts{confirm: func(string) (string, bool, error) {
			return "", false, nil
		}}.install(t)
		var out bytes.Buffer
		plan := basePlan()
		ok, err := confirmEnableNextPlan(context.Background(), &out, &out, &plan, nil, enableNextOptions{})
		if err != nil {
			t.Fatalf("confirmEnableNextPlan() error = %v", err)
		}
		if ok {
			t.Error("confirmEnableNextPlan() = true after a cancel, want false")
		}
	})

	// Deselecting every agent would capture nothing, which is not an outcome
	// this flow can apply — it keeps what was decided and says so.
	t.Run("an empty agent selection keeps the decided agents", func(t *testing.T) {
		t.Setenv("ENTIRE_TEST_TTY", "1")
		confirms := 0
		stubEnableNextPrompts{
			confirm: func(string) (string, bool, error) {
				confirms++
				if confirms == 1 {
					return enableNextConfirmEdit, true, nil
				}
				return enableNextConfirmYes, true, nil
			},
			agents:    func([]huh.Option[string], []string) ([]string, bool, error) { return nil, true, nil },
			origin:    func(repoint bool) (bool, bool, error) { return repoint, true, nil },
			telemetry: func(current bool) (bool, bool, error) { return current, true, nil },
		}.install(t)

		var out, errOut bytes.Buffer
		plan := basePlan()
		plan.existingMirror = true
		if ok, err := confirmEnableNextPlan(context.Background(), &out, &errOut, &plan, nil, enableNextOptions{}); err != nil || !ok {
			t.Fatalf("confirmEnableNextPlan() = %v, %v; want true, nil", ok, err)
		}
		if len(plan.agents) != 1 {
			t.Errorf("plan.agents = %v, want the decided single agent kept", plan.agents)
		}
		if !strings.Contains(errOut.String(), "At least one agent") {
			t.Errorf("the kept selection must be explained, got:\n%s", errOut.String())
		}
	})
}

func TestEnableNextAgentNames_RejectsUnknown(t *testing.T) {
	t.Parallel()

	if _, err := enableNextAgentNames([]string{"claude-code"}); err != nil {
		t.Fatalf("enableNextAgentNames(claude-code) error = %v", err)
	}
	// Enabling fewer agents than asked for, silently, is the failure mode this
	// guards: an unknown name is an error, not a skipped entry.
	if _, err := enableNextAgentNames([]string{"claude-code", "not-an-agent"}); err == nil {
		t.Error("enableNextAgentNames() error = nil for an unknown agent, want a rejection")
	}
	if _, err := enableNextAgentNames([]string{"  "}); err == nil {
		t.Error("enableNextAgentNames() error = nil for an empty selection, want a rejection")
	}
}
