// fakeAccessReporter answers the enable report from a scripted sequence, so
// the access-and-degrade state machine can be exercised without a backend.
// The last entry repeats once the script runs out.
type fakeAccessReporter struct {
	replies []*api.EnableRepoResponse
	errs    []error
	calls   int
}

func (f *fakeAccessReporter) ReportEnable(_ context.Context, _ string) (*api.EnableRepoResponse, error) {
	i := f.calls
	f.calls++
	if i >= len(f.replies) {
		i = len(f.replies) - 1
	}
	if f.calls-1 < len(f.errs) && f.errs[f.calls-1] != nil {
		return nil, f.errs[f.calls-1]
	}
	if i < 0 {
		return nil, errors.New("no scripted reply")
	}
	return f.replies[i], nil
}

