			t.Fatalf("enableNextEnsureAccess() = false, want true; stderr:\n%s", errOut.String())
		}
		if !strings.Contains(out.String(), "has access to acme/widget") {
			t.Errorf("output must confirm access, got:\n%s", out.String())
		}
	})

	// Not being an admin is the case that mattered most: today it exits with
	// nothing written. Here it prints the link for someone who can install it
	// and leaves the flow to land on the local answer.
	t.Run("not an admin keeps going", func(t *testing.T) {
		t.Parallel()
		var out, errOut bytes.Buffer
		deps := testEnableNextDeps()
		deps.githubAdmin = func(context.Context, string, string) (bool, error) { return false, nil }
		reporter := &fakeAccessReporter{replies: []*api.EnableRepoResponse{connectedReply(false, "https://github.com/apps/entire/installations/new")}}
		ok := enableNextEnsureAccess(context.Background(), &out, &errOut, reporter, githubIdentity(), enableNextOptions{}, deps)
		if ok {
			t.Fatal("enableNextEnsureAccess() = true, want false (the App is not installed)")
		}
		combined := out.String() + errOut.String()
		if !strings.Contains(combined, "https://github.com/apps/entire/installations/new") {
			t.Errorf("the installation link must be printed, got:\n%s", combined)
		}
		if !strings.Contains(combined, "admin") {
			t.Errorf("output must say an admin has to install it, got:\n%s", combined)
		}
		if !strings.Contains(combined, "capture") {
			t.Errorf("output must say capture still works, got:\n%s", combined)
		}
		if reporter.calls != 1 {
			t.Errorf("access was probed %d times, want 1 — a non-admin has nothing to wait for", reporter.calls)
		}
	})

	// An unknown admin answer (no gh CLI, not authenticated, API error) must
	// not be read as "not an admin": the link is offered, because it may well
	// be theirs to install.
	t.Run("an unknown admin answer still offers the link", func(t *testing.T) {
		t.Parallel()
		var out, errOut bytes.Buffer
		deps := testEnableNextDeps()
		deps.githubAdmin = func(context.Context, string, string) (bool, error) {
			return false, errEnableNextGHUnavailable
		}
		reporter := &fakeAccessReporter{replies: []*api.EnableRepoResponse{connectedReply(false, "https://github.com/apps/entire/installations/new")}}
		// Non-interactive: the link is printed and the flow degrades rather
		// than waiting on a browser nobody is looking at.
		ok := enableNextEnsureAccess(context.Background(), &out, &errOut, reporter, githubIdentity(), enableNextOptions{}, deps)
		if ok {
			t.Fatal("enableNextEnsureAccess() = true, want false")
		}
		if !strings.Contains(out.String(), "Install the GitHub App") {
			t.Errorf("the link must be offered to the caller, got:\n%s", out.String())
		}
	})

	t.Run("no installation URL", func(t *testing.T) {
		t.Parallel()
		var out, errOut bytes.Buffer
		deps := testEnableNextDeps()
		deps.githubAdmin = func(context.Context, string, string) (bool, error) { return true, nil }
		reporter := &fakeAccessReporter{replies: []*api.EnableRepoResponse{connectedReply(false, "  ")}}
		if enableNextEnsureAccess(context.Background(), &out, &errOut, reporter, githubIdentity(), enableNextOptions{}, deps) {
			t.Fatal("enableNextEnsureAccess() = true, want false")
		}
		if !strings.Contains(errOut.String(), "capture only") {
			t.Errorf("output must degrade rather than stop, got:\n%s", errOut.String())
		}
	})

	t.Run("a failed probe degrades", func(t *testing.T) {
		t.Parallel()
		var out, errOut bytes.Buffer
		reporter := &fakeAccessReporter{errs: []error{errors.New("network down")}}
		if enableNextEnsureAccess(context.Background(), &out, &errOut, reporter, githubIdentity(), enableNextOptions{}, testEnableNextDeps()) {
			t.Fatal("enableNextEnsureAccess() = true, want false")
		}
		if !strings.Contains(errOut.String(), "network down") {
			t.Errorf("the cause must be reported, got:\n%s", errOut.String())
		}
	})
}

func TestWaitForEnableNextAccess(t *testing.T) {
	t.Parallel()

	t.Run("returns once the App can reach the repo", func(t *testing.T) {
		t.Parallel()
		reporter := &fakeAccessReporter{replies: []*api.EnableRepoResponse{
			connectedReply(false, ""),
			connectedReply(false, ""),
			connectedReply(true, ""),
		}}
		if err := waitForEnableNextAccess(context.Background(), reporter, "u", time.Millisecond, 3); err != nil {
			t.Fatalf("waitForEnableNextAccess() error = %v", err)
		}
		if reporter.calls != 3 {
			t.Errorf("probes = %d, want 3", reporter.calls)
		}
	})

	// A single transient error while someone is clicking through GitHub is not
	// a reason to give up; a run of them is.
	t.Run("tolerates a transient failure", func(t *testing.T) {
		t.Parallel()
		reporter := &fakeAccessReporter{
			replies: []*api.EnableRepoResponse{connectedReply(false, ""), connectedReply(true, "")},
			errs:    []error{errors.New("blip")},
		}
		if err := waitForEnableNextAccess(context.Background(), reporter, "u", time.Millisecond, 3); err != nil {
			t.Fatalf("waitForEnableNextAccess() error = %v", err)
		}
	})

	t.Run("gives up after consecutive failures", func(t *testing.T) {
		t.Parallel()
		reporter := &fakeAccessReporter{errs: []error{
			errors.New("blip"), errors.New("blip"), errors.New("blip"),
		}}
		err := waitForEnableNextAccess(context.Background(), reporter, "u", time.Millisecond, 3)
		if err == nil {
			t.Fatal("waitForEnableNextAccess() error = nil, want a failure")
		}
	})

	t.Run("honours the deadline", func(t *testing.T) {
		t.Parallel()
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Millisecond)
		defer cancel()
		reporter := &fakeAccessReporter{replies: []*api.EnableRepoResponse{connectedReply(false, "")}}
		err := waitForEnableNextAccess(ctx, reporter, "u", time.Millisecond, 100)
		if !errors.Is(err, context.DeadlineExceeded) {
			t.Fatalf("waitForEnableNextAccess() error = %v, want DeadlineExceeded", err)
		}
	})
}

func TestEnableNextTargetRegion(t *testing.T) {
	t.Parallel()

	regions := []regionChoice{
		{slug: "us-east-2", jurisdiction: "us", host: "aws-us-east-2.entire.io", isDefault: true},
		{slug: "eu-central-1", jurisdiction: "eu", host: "aws-eu-central-1.entire.io", isDefault: true},
	}

	tests := []struct {
		name         string
		regions      []regionChoice
		jurisdiction string
		selector     string
		wantHost     string
		wantErr      bool
	}{
		{
			// The whole point of not asking: the account's home jurisdiction
			// decides, and it is disclosed in the plan.
			name:         "the login's home jurisdiction decides",
			regions:      regions,
			jurisdiction: "eu",
			wantHost:     "aws-eu-central-1.entire.io",
		},
		{
			name:         "--region by slug",
			regions:      regions,
			jurisdiction: "eu",
			selector:     "us-east-2",
			wantHost:     "aws-us-east-2.entire.io",
		},
		{
			name:         "--region by host",
			regions:      regions,
			jurisdiction: "eu",
			selector:     "AWS-US-EAST-2.entire.io",
			wantHost:     "aws-us-east-2.entire.io",
		},
		{
			name:         "--region naming nothing in the catalog is an error",
			regions:      regions,
			jurisdiction: "eu",
			selector:     "moon-base-1",
			wantErr:      true,
		},
		{
			// An account whose home jurisdiction the catalog does not cover
			// still gets a region rather than a failure.
			name:         "an unknown jurisdiction falls back to the catalog default",
			regions:      regions,
			jurisdiction: "au",
			wantHost:     "aws-us-east-2.entire.io",
		},
		{
			// An unreadable catalog costs the region question, not the
			// connect path.
			name:     "an empty catalog falls back to the default cluster",
			regions:  nil,
			wantHost: defaultClusterHost,
		},
		{
			name:     "an empty catalog trusts an explicit host",
			regions:  nil,
			selector: "aws-eu-central-1.entire.io",
			wantHost: "aws-eu-central-1.entire.io",
		},
		{
			name:     "an empty catalog still rejects a bogus host",
			regions:  nil,
			selector: "not a host",
			wantErr:  true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got, err := enableNextTargetRegion(tt.regions, tt.jurisdiction, tt.selector)
			if tt.wantErr {
				if err == nil {
					t.Fatalf("enableNextTargetRegion() = %+v, want an error", got)
				}
				return
			}
			if err != nil {
				t.Fatalf("enableNextTargetRegion() error = %v", err)
			}
			if got.host != tt.wantHost {
				t.Errorf("region host = %q, want %q", got.host, tt.wantHost)
			}
		})
	}
}

// TestEnableNextExistingPlacement pins that a repository someone else on the
// team already onboarded keeps its region: the second person's home
// jurisdiction must not create a second placement.
func TestEnableNextExistingPlacement(t *testing.T) {
	t.Parallel()

	placements := []coreapi.ResolvedPlacement{
		{ClusterHost: "aws-eu-central-1.entire.io", Cell: coreapi.NewOptString("eu-central-1")},
		{ClusterHost: "aws-us-east-2.entire.io", Cell: coreapi.NewOptString("us-east-2")},
	}

	if _, ok := enableNextExistingPlacement(nil, ""); ok {
		t.Error("enableNextExistingPlacement(nil) reported a placement")
	}
	got, ok := enableNextExistingPlacement(placements, "")
	if !ok || got.ClusterHost != "aws-eu-central-1.entire.io" {
		t.Errorf("placement = %+v (ok=%v), want the first placement", got, ok)
	}
	got, ok = enableNextExistingPlacement(placements, "us-east-2")
	if !ok || got.ClusterHost != "aws-us-east-2.entire.io" {
		t.Errorf("placement = %+v (ok=%v), want the --region match", got, ok)
	}
	// A selector naming no existing placement still adopts one rather than
	// creating a second: the repository's data already lives somewhere.
	got, ok = enableNextExistingPlacement(placements, "moon-base-1")
	if !ok || got.ClusterHost != "aws-eu-central-1.entire.io" {
		t.Errorf("placement = %+v (ok=%v), want the first placement", got, ok)
	}
}

// TestEnableNextRegionFor pins that an existing placement is named in the
// catalog's terms when the catalog knows it, so the plan shows a slug rather
// than a bare host.
func TestEnableNextRegionFor(t *testing.T) {
	t.Parallel()

	regions := []regionChoice{{slug: "eu-central-1", jurisdiction: "eu", host: "aws-eu-central-1.entire.io"}}
	placement := coreapi.ResolvedPlacement{ClusterHost: "AWS-EU-CENTRAL-1.entire.io"}
	if got := enableNextRegionFor(placement, regions); got.slug != "eu-central-1" {
		t.Errorf("region = %+v, want the catalog's eu-central-1", got)
	}
	// Not in the catalog: fall back to what the placement itself says.
	placement = coreapi.ResolvedPlacement{
		ClusterHost:  "aws-ap-south-1.entire.io",
		Cell:         coreapi.NewOptString("ap-south-1"),
		Jurisdiction: coreapi.NewOptString("in"),
	}
	got := enableNextRegionFor(placement, regions)
	if got.slug != "ap-south-1" || got.host != "aws-ap-south-1.entire.io" || got.jurisdiction != "in" {
		t.Errorf("region = %+v, want the placement's own coordinates", got)
	}
}

