// before it asks anything. Every shape below is a real starting situation, and
// none of them is an error here: a repo the connect path cannot use is
// something the connect path reports, not something identity resolution
// refuses.
func TestResolveEnableNextIdentity(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name              string
		remote            string
		wantOwner         string
		wantRepo          string
		wantLabel         string
		wantIsEntire      bool
		wantCleanRemote   string
		wantNoGitHubCoord bool
	}{
