			name:            "ssh GitHub origin",
			remote:          "git@github.com:acme/widget.git",
			wantOwner:       "acme",
			wantRepo:        "widget",
			wantLabel:       "acme/widget",
			wantCleanRemote: "https://github.com/acme/widget.git",
		},
		{
