			// re-running on it is not a special case, it just finds the mirror
			// already there.
			name:            "an origin already pointing through Entire",
			remote:          "entire://aws-eu-central-1.entire.io/gh/acme/widget",
			wantOwner:       "acme",
			wantRepo:        "widget",
			wantLabel:       "acme/widget",
			wantIsEntire:    true,
			wantCleanRemote: "https://github.com/acme/widget.git",
		},
		{
			// Credentials in the remote must not reach the enable report.
			name:            "credentials are stripped from the reported remote",
			remote:          "REDACTED",
			wantOwner:       "acme",
			wantRepo:        "widget",
			wantLabel:       "acme/widget",
			wantCleanRemote: "https://github.com/acme/widget.git",
		},
		{
			name:              "a non-GitHub origin has no coordinates to connect",
			remote:            "https://gitlab.com/acme/widget.git",
			wantNoGitHubCoord: true,
		},
		{
			name:              "no origin at all",
			remote:            "",
			wantNoGitHubCoord: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			dir := t.TempDir()
			testutil.InitRepo(t, dir)
			if tt.remote != "" {
				if _, err := gitRunner(context.Background(), dir, "remote", "add", "origin", tt.remote); err != nil {
					t.Fatalf("git remote add: %v", err)
				}
			}

			got := resolveEnableNextIdentity(context.Background(), dir)
			if tt.wantNoGitHubCoord {
				if got.isGitHub() {
					t.Fatalf("identity = %+v, want no GitHub coordinates", got)
				}
				if got.label != filepath.Base(dir) {
					t.Errorf("label = %q, want the directory name %q", got.label, filepath.Base(dir))
				}
				if got.hasOrigin != (tt.remote != "") {
					t.Errorf("hasOrigin = %v, want %v", got.hasOrigin, tt.remote != "")
				}
				return
			}
			if got.owner != tt.wantOwner || got.repo != tt.wantRepo {
				t.Errorf("owner/repo = %q/%q, want %q/%q", got.owner, got.repo, tt.wantOwner, tt.wantRepo)
			}
			if got.label != tt.wantLabel {
				t.Errorf("label = %q, want %q", got.label, tt.wantLabel)
			}
			if got.cleanRemote != tt.wantCleanRemote {
				t.Errorf("cleanRemote = %q, want %q", got.cleanRemote, tt.wantCleanRemote)
			}
			if got.originIsEntire != tt.wantIsEntire {
				t.Errorf("originIsEntire = %v, want %v", got.originIsEntire, tt.wantIsEntire)
			}
		})
	}
}

// TestRepointEnableNextOrigin pins the remote wiring this flow commits to: one
// remote, one URL, both directions. Nothing is added alongside origin and the
// previous URL is not parked under a second remote — the simplification is the
// point, so a future "helpful" preserve step should fail this test.
func TestRepointEnableNextOrigin(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	if _, err := gitRunner(context.Background(), dir, "remote", "add", "origin", "https://github.com/acme/widget.git"); err != nil {
		t.Fatalf("git remote add: %v", err)
	}

	ident := resolveEnableNextIdentity(context.Background(), dir)
	plan := enableNextPlan{
		connect:       true,
		region:        regionChoice{slug: "eu-central-1", host: "aws-eu-central-1.entire.io"},
		repointOrigin: true,
		githubOrigin:  true,
	}

	var out bytes.Buffer
	if err := repointEnableNextOrigin(context.Background(), &out, ident, plan); err != nil {
		t.Fatalf("repointEnableNextOrigin() error = %v", err)
	}

	const want = "entire://aws-eu-central-1.entire.io/gh/acme/widget"
	fetchURL, err := gitRunner(context.Background(), dir, "remote", "get-url", "origin")
	if err != nil {
		t.Fatalf("git remote get-url origin: %v", err)
	}
	if fetchURL != want {
		t.Errorf("origin fetch URL = %q, want %q", fetchURL, want)
	}
	pushURL, err := gitRunner(context.Background(), dir, "remote", "get-url", "--push", "origin")
	if err != nil {
		t.Fatalf("git remote get-url --push origin: %v", err)
	}
	if pushURL != want {
		t.Errorf("origin push URL = %q, want %q — one URL serves both directions", pushURL, want)
	}
	remotes, err := listGitRemotes(context.Background(), dir)
	if err != nil {
		t.Fatalf("listGitRemotes: %v", err)
	}
	if len(remotes) != 1 {
		t.Errorf("remotes = %v, want origin alone (no forge or upstream remote is added)", remotes)
	}
	// The replaced URL only exists in this output now, so it has to be there.
	if !strings.Contains(out.String(), "https://github.com/acme/widget.git") {
		t.Errorf("output must report the replaced URL, got:\n%s", out.String())
	}

	// Re-running is a no-op that says so rather than rewriting the same value.
	out.Reset()
	ident = resolveEnableNextIdentity(context.Background(), dir)
	if err := repointEnableNextOrigin(context.Background(), &out, ident, plan); err != nil {
		t.Fatalf("repointEnableNextOrigin() second call error = %v", err)
	}
	if !strings.Contains(out.String(), "already pointed there") {
		t.Errorf("a second run must report a no-op, got:\n%s", out.String())
	}
}

// newEnableNextTestCmd wires a command whose output the test can read.
func newEnableNextTestCmd(t *testing.T, out, errOut *bytes.Buffer) *cobra.Command {
	t.Helper()
	cmd := newEnableNextCmd()
	cmd.SetContext(context.Background())
	cmd.SetOut(out)
	cmd.SetErr(errOut)
	return cmd
