// TestRunEnableNext_LocalOnly runs the "Just my repo" answer end to end. It is
// the answer that must work with no account and no network, so nothing here is
// stubbed except the answer itself.
func TestRunEnableNext_LocalOnly(t *testing.T) {
	dir := setupTestRepo(t)

	var out, errOut bytes.Buffer
	cmd := newEnableNextTestCmd(t, &out, &errOut)
	o := enableNextOptions{localOnly: true, agents: []string{"claude-code"}, telemetry: true}
	if err := runEnableNext(cmd, o, testEnableNextDeps()); err != nil {
		t.Fatalf("runEnableNext() error = %v\nstdout:\n%s\nstderr:\n%s", err, out.String(), errOut.String())
	}

	s, err := settings.Load(cmd.Context())
	if err != nil {
		t.Fatalf("settings.Load() error = %v", err)
	}
	if !s.Enabled {
		t.Error("settings.Enabled = false, want true")
	}
	if s.Telemetry == nil || !*s.Telemetry {
		t.Errorf("settings.Telemetry = %v, want an explicit true (a nil value reads as disabled)", s.Telemetry)
	}
	if _, err := os.Stat(filepath.Join(dir, ".claude", "settings.json")); err != nil {
		t.Errorf("agent hooks were not installed: %v", err)
	}

	got := out.String()
	for _, want := range []string{
		"Done. Sessions are recorded in this repo.",
		"Chosen for you — change any of these:",
		"entire agent add|remove <name>",
		"git add .entire && git commit",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("output must contain %q, got:\n%s", want, got)
		}
	}
	// The local answer has nothing to say about regions or origin.
	for _, unwanted := range []string{"region", "origin"} {
		if strings.Contains(got, unwanted) {
			t.Errorf("output must not mention %q for the local answer, got:\n%s", unwanted, got)
		}
	}
}

// TestRunEnableNext_ConnectDegradesToLocal is the flow's central promise: the
// connect answer failing leaves a working setup rather than an aborted
// command. Everything the local answer writes is still written, and the reason
// is on stderr.
func TestRunEnableNext_ConnectDegradesToLocal(t *testing.T) {
	setupTestRepo(t)
	if _, err := gitRunner(context.Background(), ".", "remote", "add", "origin", "https://github.com/acme/widget.git"); err != nil {
		t.Fatalf("git remote add: %v", err)
	}

	deps := testEnableNextDeps()
	// No stored login and no terminal to sign in from.
	deps.resolveAuth = func(context.Context) (statusTarget, error) { return statusTarget{}, nil }

	var out, errOut bytes.Buffer
	cmd := newEnableNextTestCmd(t, &out, &errOut)
	o := enableNextOptions{connect: true, agents: []string{"claude-code"}, telemetry: true}
	if err := runEnableNext(cmd, o, deps); err != nil {
		t.Fatalf("runEnableNext() error = %v (the connect path must degrade, not fail)\nstderr:\n%s", err, errOut.String())
	}

	s, err := settings.Load(cmd.Context())
	if err != nil {
		t.Fatalf("settings.Load() error = %v", err)
	}
	if !s.Enabled {
		t.Error("settings.Enabled = false — a failed connect must still leave capture enabled")
	}
	if !strings.Contains(errOut.String(), "entire login") {
		t.Errorf("stderr must name what to do about it, got:\n%s", errOut.String())
	}
	if !strings.Contains(out.String(), "Sessions are recorded in this repo.") {
		t.Errorf("the closing summary must reflect the local outcome, got:\n%s", out.String())
	}
	// origin is untouched by a degraded connect.
	origin, err := gitRunner(context.Background(), ".", "remote", "get-url", "origin")
	if err != nil {
		t.Fatalf("git remote get-url origin: %v", err)
	}
	if origin != "https://github.com/acme/widget.git" {
		t.Errorf("origin = %q, want it untouched", origin)
	}
}

// TestRunEnableNext_UnknownAgentIsRejected pins that a bad --agent value fails
// before anything is written, so a typo cannot leave a half-configured repo.
func TestRunEnableNext_UnknownAgentIsRejected(t *testing.T) {
	dir := setupTestRepo(t)

	var out, errOut bytes.Buffer
	cmd := newEnableNextTestCmd(t, &out, &errOut)
	o := enableNextOptions{localOnly: true, agents: []string{"not-an-agent"}}
	if err := runEnableNext(cmd, o, testEnableNextDeps()); err == nil {
		t.Fatal("runEnableNext() error = nil for an unknown agent, want a rejection")
	}
	if _, err := os.Stat(filepath.Join(dir, ".entire", "settings.json")); !os.IsNotExist(err) {
		t.Errorf("settings must not be written for a rejected invocation (stat err = %v)", err)
	}
}
