package cli

import (
	"fmt"
	"io"
	"strings"

	"charm.land/lipgloss/v2"
)

// enableNextRender is how enable-next paints everything it prints. It exists
// so the flow has one visual hierarchy rather than a per-call-site one:
//
//   - headings (what is about to happen, what happened) are bold;
//   - the things we decided — a region, an agent list, a value — are printed
//     in the terminal's own foreground, so they are the brightest thing on
//     their line;
//   - everything that frames them — labels, parentheticals, the disclosure
//     above the question — is dim;
//   - commands and URLs are accent-coloured, because they are the parts the
//     reader is meant to act on.
//
// Colour is resolved from the writer (statusStyles → interactive.ShouldStyle),
// so a pipe, NO_COLOR, or a terminal that cannot render ANSI gets the same
// text with no escape bytes — the alignment does the work there.
type enableNextRender struct {
	w io.Writer
	s statusStyles
}

func newEnableNextRender(w io.Writer) enableNextRender {
	return enableNextRender{w: w, s: newStatusStyles(w)}
}

// enableNextStepWidth is the column the detail text on a ✓/✗ line starts in.
// Wide enough for the longest action this flow prints ("Wrote
// .entire/settings.json"), so the details line up as a column instead of
// drifting with the action's length.
const enableNextStepWidth = 30

func (r enableNextRender) blank() { fmt.Fprintln(r.w) }

func (r enableNextRender) line(text string) { fmt.Fprintln(r.w, text) }

// heading is a section title: bold, because it is where the reader's eye
// should land when scrolling back through a completed run.
func (r enableNextRender) heading(text string) {
	fmt.Fprintf(r.w, "  %s\n", r.s.render(r.s.bold, text))
}

// context is framing prose — what was detected, what happens either way. Dim,
// so it never competes with a decision or a question.
func (r enableNextRender) context(text string) {
	fmt.Fprintf(r.w, "  %s\n", r.s.render(r.s.dim, text))
}

// step records one thing that was done. The action keeps the terminal's
// default foreground; the detail beside it is dim, because it explains the
// action rather than adding a second one.
func (r enableNextRender) step(action, detail string) {
	r.mark(r.s.render(r.s.green, "✓"), action, detail)
}

// blocked records one thing that could not be done. Warning-coloured rather
// than red on purpose: every one of these leaves a working setup behind, so it
// is a diversion, not a failure.
func (r enableNextRender) blocked(action, detail string) {
	r.mark(r.s.render(r.s.yellow, "✗"), action, detail)
}

func (r enableNextRender) mark(symbol, action, detail string) {
	if detail == "" {
		fmt.Fprintf(r.w, "  %s %s\n", symbol, action)
		return
	}
	fmt.Fprintf(r.w, "  %s %s  %s\n", symbol, padRight(action, enableNextStepWidth), r.s.render(r.s.dim, detail))
}

// detail is a continuation line under a step or a blocked step: an
// installation link, a command to hand to someone else, the URL a replaced
// remote used to point at.
func (r enableNextRender) detail(text string) {
	fmt.Fprintf(r.w, "    %s\n", r.s.render(r.s.dim, text))
}

// command prints something the reader is meant to run. Accent-coloured, and
// never dimmed: a command the eye slides past is a command nobody runs.
func (r enableNextRender) command(indent, text string) {
	fmt.Fprintf(r.w, "%s%s\n", indent, r.s.render(r.s.magenta, text))
}

// labelled prints a "command: value" pair where the label frames a command,
// used by the blocked branches that name what to run next.
func (r enableNextRender) labelled(label, command string) {
	fmt.Fprintf(r.w, "    %s  %s\n", r.s.render(r.s.dim, padRight(label, 26)), r.s.render(r.s.magenta, command))
}

// url prints a link. Same treatment as a command: it is there to be used.
func (r enableNextRender) url(indent, text string) {
	fmt.Fprintf(r.w, "%s%s\n", indent, r.s.render(r.s.magenta, text))
}

// planRow prints one decision in the pre-apply plan: a dim label, the value in
// full brightness, and a dim note saying what kind of change it is.
func (r enableNextRender) planRow(label, value, note string, labelWidth int) {
	line := fmt.Sprintf("    %s   %s", r.s.render(r.s.dim, padRight(label, labelWidth)), value)
	if note != "" {
		line += "  " + r.s.render(r.s.dim, note)
	}
	fmt.Fprintln(r.w, line)
}

// decisionRow prints one decision in the closing summary, with the command
// that changes it. Three weights on one line — dim label, bright value, accent
// command — is what makes the block scannable in either direction: down the
// values to see what was decided, down the commands to see what to run.
func (r enableNextRender) decisionRow(label, value, note, change string, labelWidth, valueWidth int) {
	value = padRight(value, valueWidth)
	if note != "" {
		value = padRight(value+"  "+note, valueWidth)
	}
	fmt.Fprintf(r.w, "    %s  %s   %s\n",
		r.s.render(r.s.dim, padRight(label, labelWidth)),
		r.enableNextValue(value, note),
		r.s.render(r.s.magenta, change))
}

// enableNextValue renders a decision's value with its note dimmed, so the two
// keep their weights even though they share a padded column.
func (r enableNextRender) enableNextValue(padded, note string) string {
	if note == "" {
		return padded
	}
	value, rest, ok := strings.Cut(padded, "  "+note)
	if !ok {
		return padded
	}
	return value + "  " + r.s.render(r.s.dim, note) + rest
}

// padRight pads to width with spaces, leaving anything longer untouched.
// Applied to raw text before styling: padding a string that already carries
// ANSI escapes counts the escape bytes and breaks the column.
func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

// enableNextStyleWidth is the printable width of a styled string, used where a
// caller has to align around text this renderer already coloured.
func enableNextStyleWidth(s string) int { return lipgloss.Width(s) }
