package cli

import (
	"bytes"
	"strings"
	"testing"

	"charm.land/lipgloss/v2"

	"github.com/entireio/cli/cmd/entire/cli/palette"
)

// styledEnableNextRender builds a renderer with colour forced on. `go test`
// never has a real terminal writer, so newStatusStyles would resolve to the
// plain path and the weights this file exists to pin would all be identical.
func styledEnableNextRender(w *bytes.Buffer) enableNextRender {
	return enableNextRender{w: w, s: statusStyles{
		colorEnabled: true,
		green:        lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Success)),
		yellow:       lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)),
		magenta:      lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Magenta)),
		bold:         lipgloss.NewStyle().Bold(true),
		dim:          lipgloss.NewStyle().Faint(true),
	}}
}

// TestEnableNextRender_ThreeWeightsOnADecisionRow pins the contrast the
// closing summary is built around: the label that frames a decision, the
// decision itself, and the command that changes it must not render alike. A
// block where all three read at the same weight is the thing this renderer
// exists to prevent.
func TestEnableNextRender_ThreeWeightsOnADecisionRow(t *testing.T) {
	t.Parallel()

	var buf bytes.Buffer
	styledEnableNextRender(&buf).decisionRow("region", "eu-central-1", "new mirror", "entire repo mirror create", 9, 24)
	got := buf.String()

	dim := lipgloss.NewStyle().Faint(true)
	accent := lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Magenta))

	if !strings.Contains(got, dim.Render("region   ")) {
		t.Errorf("the label must be dim, got %q", got)
	}
	if !strings.Contains(got, dim.Render("new mirror")) {
		t.Errorf("the note must be dim, got %q", got)
	}
	if !strings.Contains(got, accent.Render("entire repo mirror create")) {
		t.Errorf("the change command must be accent-coloured, got %q", got)
	}
	// The value itself carries no escape of its own: it inherits the
	// terminal's foreground, which is what makes it the brightest thing on
	// the line in both light and dark themes.
	if !strings.Contains(got, "\x1b[m eu-central-1") && !strings.Contains(got, "  eu-central-1") {
		t.Errorf("the value must be unstyled, got %q", got)
	}
	if strings.Contains(got, dim.Render("eu-central-1")) {
		t.Errorf("the value must not be dimmed like its label, got %q", got)
	}
}

// TestEnableNextRender_PlainWriterHasNoEscapes pins that every weight
// collapses to plain text off a terminal (a pipe, NO_COLOR, a legacy console),
// where the alignment has to carry the hierarchy on its own.
func TestEnableNextRender_PlainWriterHasNoEscapes(t *testing.T) {
	t.Parallel()

	var buf bytes.Buffer
	r := newEnableNextRender(&buf) // a bytes.Buffer is never a terminal
	r.heading("Chosen for you — change any of these:")
	r.decisionRow("region", "eu-central-1", "new mirror", "entire repo mirror create", 9, 24)
	r.step("Installed hooks", "Claude Code")
	r.blocked("No access", "the GitHub App is not installed")

	got := buf.String()
	if strings.Contains(got, "\x1b") {
		t.Fatalf("no escape byte may reach a non-terminal writer, got %q", got)
	}
	for _, want := range []string{
		"  Chosen for you — change any of these:",
		"    region     eu-central-1  new mirror   entire repo mirror create",
		"  ✓ Installed hooks                Claude Code",
		"  ✗ No access                      the GitHub App is not installed",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("output must contain %q, got:\n%s", want, got)
		}
	}
}

// TestEnableNextRender_ColumnsSurviveWideRunes pins that padding counts runes,
// not bytes: this flow prints em dashes and arrows, and a byte-counted pad
// puts the command column in a different place on every row.
func TestEnableNextRender_ColumnsSurviveWideRunes(t *testing.T) {
	t.Parallel()

	var buf bytes.Buffer
	r := newEnableNextRender(&buf)
	r.decisionRow("origin", "Entire", "forwarded to GitHub", "entire repo mirror use", 9, 27)
	r.decisionRow("telemetry", "on", "", "entire configure --telemetry=false", 9, 27)

	lines := strings.Split(strings.TrimRight(buf.String(), "\n"), "\n")
	if len(lines) != 2 {
		t.Fatalf("expected two rows, got %q", buf.String())
	}
	first := strings.Index(lines[0], "entire repo mirror use")
	second := strings.Index(lines[1], "entire configure")
	if first != second {
		t.Errorf("command column starts at %d and %d — the rows do not line up:\n%s", first, second, buf.String())
	}
}
