// sgrPrefix returns the leading ANSI sequence of a rendered string (up to and
// including its first "m"), which is what identifies the colour a style
// applied without depending on the text it was applied to.
func sgrPrefix(rendered string) string {
	if !strings.HasPrefix(rendered, "\x1b[") {
		return ""
	}
	end := strings.Index(rendered, "m")
	if end < 0 {
		return ""
	}
	return rendered[:end+1]
}

// TestEnableNextTheme_SelectionMatchesTheBlockedMark pins the one hue this
// flow's forms differ from the rest of the CLI by: the selection is painted in
// the same slot as the ✗ that fronts a blocked step, not the CLI-wide magenta
// accent. Asserted against the palette rather than a literal escape, so the
// two can only ever move together.
func TestEnableNextTheme_SelectionMatchesTheBlockedMark(t *testing.T) {
	t.Parallel()

	blocked := lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning))
	wantForeground := sgrPrefix(blocked.Render("✗"))
	if wantForeground == "" {
		t.Fatal("the blocked mark renders no colour to match against")
	}
	accent := sgrPrefix(lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Accent)).Render("x"))

	for _, dark := range []bool{true, false} {
		styles := enableNextTheme().Theme(dark)
		selection := map[string]string{
			"select pointer":      styles.Focused.SelectSelector.Render("x"),
			"multiselect pointer": styles.Focused.MultiSelectSelector.Render("x"),
			"selected option":     styles.Focused.SelectedOption.Render("x"),
			"selected prefix":     styles.Focused.SelectedPrefix.Render("x"),
		}
		for what, rendered := range selection {
			if got := sgrPrefix(rendered); got != wantForeground {
				t.Errorf("dark=%v: the %s renders %q, want the blocked mark's %q", dark, what, got, wantForeground)
			}
			if accent != "" && strings.Contains(rendered, accent) {
