		// The confirm's chip is a background rather than a foreground, so it
		// is matched against the same slot used as a background.
		button := styles.Focused.FocusedButton.Render(" Yes ")
		wantChip := sgrPrefix(lipgloss.NewStyle().Background(lipgloss.Color(palette.Warning)).Render(" "))
		if wantChip == "" || !strings.Contains(button, wantChip) {
			t.Errorf("dark=%v: the focused button %q does not carry the chip %q", dark, button, wantChip)
